[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

function Parse-TimoFile {
    param([string]$filePath, [int]$grade)

    if (!(Test-Path $filePath)) { return @() }
    $lines = Get-Content $filePath -Encoding UTF8

    $questions = @()
    $currentQ = $null
    $inQuestions = $false
    $currentExam = "Vòng loại - Đề số 1"
    $currentTopic = "Tư duy logic"

    # We will look for patterns like:
    # 1. Given ... / Cho ...
    # A. ... B. ...

    $i = 0
    while ($i -lt $lines.Count) {
        $line = $lines[$i].Trim()

        # Check round / exam title
        if ($line -match "PRELIMINARY ROUND") {
            $inQuestions = $true
            $currentExam = "Vòng loại"
        } elseif ($line -match "HEAT ROUND") {
            $inQuestions = $true
            $currentExam = "Vòng quốc gia"
        } elseif ($line -match "ĐỀ SỐ\s*(\d+)") {
            $currentExam = "$currentExam - Đề số $($Matches[1])"
        } elseif ($line -match "(Logical [Tt]hinking|Arithmetic|Number [Tt]heory|Geometry|Combinatorics)") {
            $currentTopic = $line
        } elseif ($line -match "^\s*(\d+)\.\s*(.*)") {
            # Start of a new question
            $qNum = [int]$Matches[1]
            if ($qNum -ge 1 -and $qNum -le 30) {
                if ($currentQ -ne $null) {
                    $questions += $currentQ
                }

                $qText = $Matches[2]
                $currentQ = [PSCustomObject]@{
                    id = "$grade-$currentExam-$qNum"
                    grade = $grade
                    exam = "TIMO"
                    round = $currentExam
                    topic = $currentTopic
                    num = $qNum
                    textLines = @($qText)
                    options = @()
                    answer = ""
                    type = "mc"
                }
            }
        } elseif ($currentQ -ne $null) {
            # Check options
            if ($line -match "^[A-D]\.\s*") {
                $currentQ.options += $line
            } elseif ($line -match " " -or $line -match "LỜI GIẢI" -or $line -match "ĐÁP ÁN THAM KHẢO") {
                # End of questions section
                if ($currentQ -ne $null) {
                    $questions += $currentQ
                    $currentQ = $null
                }
                if ($line -match "ĐÁP ÁN THAM KHẢO") {
                    break
                }
            } else {
                if ($line -ne "" -and -not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC")) {
                    $currentQ.textLines += $line
                }
            }
        }
        $i++
    }

    if ($currentQ -ne $null) {
        $questions += $currentQ
    }

    return $questions
}

$allQuestions = @()
1..5 | ForEach-Object {
    $txtPath = "C:\Users\HNBV3384\.gemini\antigravity\scratch\extracted_texts\TIMO_$_.txt"
