function Parse-FullTimo {
    param([string]$txtPath, [int]$grade)

    if (!(Test-Path $txtPath)) { return @() }
    $lines = Get-Content $txtPath -Encoding UTF8

    # 1. Parse Solutions (LỜI GIẢI CHI TIẾT)
    # Map key: "$roundName-$qNum" -> { answer, explanation }
    $solutions = @{}
    $inSolutions = $false
    $curRound = "Vòng loại - Đề số 1"
    $curSolQ = $null
    $curExplLines = @()

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].Trim()

        if ($line -match "LỜI GIẢI CHI TIẾT") {
            $inSolutions = $true
            continue
        }
        if ($line -match "ĐÁP ÁN THAM KHẢO" -or $line -match "Answer Sheet") {
            if ($inSolutions) { break }
        }

        if ($inSolutions) {
            if ($line -match "PRELIMINARY ROUND|VÒNG LOẠI") {
                $curRound = "Vòng loại"
            } elseif ($line -match "HEAT ROUND|VÒNG QUỐC GIA") {
                $curRound = "Vòng quốc gia"
            } elseif ($line -match "ĐỀ SỐ\s*(\d+)") {
                $curRound = "$curRound - Đề số $($Matches[1])"
            } elseif ($line -match "^\s*(\d+)\.\s*(.*)") {
                $qNum = [int]$Matches[1]
                if ($qNum -ge 1 -and $qNum -le 30) {
                    # Save previous solution
                    if ($curSolQ -ne $null) {
                        $key = "$curRound-$curSolQ"
                        $solText = $curExplLines -join "`n"
                        $ans = ""
                        if ($solText -match "Đáp số:\s*([A-D]|\d+)") {
                            $ans = $Matches[1].Trim()
                        }
                        $solutions[$key] = @{
                            answer = $ans
                            explanation = $solText
                        }
                    }
                    $curSolQ = $qNum
                    $curExplLines = @($Matches[2])
                } else {
                    if ($curSolQ -ne $null) { $curExplLines += $line }
                }
            } else {
                if ($curSolQ -ne $null) {
                    if (-not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC") -and -not ($line -match "^\d+$")) {
                        $curExplLines += $line
                    }
                }
            }
        }
    }
    # Save the last solution
    if ($curSolQ -ne $null) {
        $key = "$curRound-$curSolQ"
        $solText = $curExplLines -join "`n"
        $ans = ""
        if ($solText -match "Đáp số:\s*([A-D]|\d+)") { $ans = $Matches[1].Trim() }
        $solutions[$key] = @{ answer = $ans; explanation = $solText }
    }

    Write-Host "Grade $grade : Parsed $($solutions.Count) solutions."

    # 2. Parse Questions
    $questions = @()
    $currentQ = $null
    $inQuestions = $false
    $currentExam = "Vòng loại - Đề số 1"
    $currentTopic = "Tư duy logic"

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].Trim()

        if ($line -match "PRELIMINARY ROUND") {
            $inQuestions = $true
            $currentExam = "Vòng loại"
        } elseif ($line -match "HEAT ROUND") {
            $inQuestions = $true
            $currentExam = "Vòng quốc gia"
        } elseif ($line -match "ĐỀ SỐ\s*(\d+)") {
            $currentExam = "$currentExam - Đề số $($Matches[1])"
        } elseif ($line -match "(Logical [Tt]hinking|Arithmetic|Number [Tt]heory|Geometry|Combinatorics)") {
            $currentTopic = $line
        } elseif ($line -match "LỜI GIẢI CHI TIẾT") {
            if ($currentQ -ne $null) { $questions += $currentQ }
            break
        } elseif ($inQuestions -and $line -match "^\s*(\d+)\.\s*(.*)") {
            $qNum = [int]$Matches[1]
            if ($qNum -ge 1 -and $qNum -le 30) {
                if ($currentQ -ne $null) {
                    $questions += $currentQ
                }

                $key = "$currentExam-$qNum"
                $ansInfo = $solutions[$key]
                $ansVal = ""
                $explVal = ""
                if ($ansInfo -ne $null) {
                    $ansVal = $ansInfo.answer
                    $explVal = $ansInfo.explanation
                }

                $currentQ = [PSCustomObject]@{
                    id = "$grade-$currentExam-$qNum"
                    grade = $grade
                    exam = "TIMO"
                    round = $currentExam
                    topic = $currentTopic
                    num = $qNum
                    text = $Matches[2]
                    textLines = @($Matches[2])
                    options = @()
                    answer = $ansVal
                    explanation = $explVal
                    type = "mc"
                }
            }
        } elseif ($currentQ -ne $null) {
            if ($line -match "^[A-D]\.\s*") {
                $currentQ.options += $line
            } else {
                if ($line -ne "" -and -not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC") -and -not ($line -match "^\d+$")) {
                    $currentQ.textLines += $line
                }
            }
        }
    }
    if ($currentQ -ne $null) { $questions += $currentQ }

    # Clean up text
    foreach ($q in $questions) {
        $q.text = ($q.textLines -join "`n").Trim()
        if ($q.options.Count -eq 0 -and $q.answer -ne "") {
            $q.type = "fill"
        }
    }

    return $questions
}

