    if (!(Test-Path $txtPath)) { return @() }
    $lines = Get-Content $txtPath -Encoding UTF8

    # 1. Parse Solutions (LỜI GIẢI CHI TIẾT)
    $solutions = @{}
    $inSolutions = $false
    $curRoundType = "Vòng loại"
    $curDeSo = "Đề số 1"
    $curSolQ = $null
    $curExplLines = @()

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].Trim()

        if ($line -match "LỜI GIẢI CHI TIẾT" -and $line -notmatch "\(") {
            $inSolutions = $true
            continue
        }
        if ($inSolutions -and ($line -match "ĐÁP ÁN THAM KHẢO" -or $line -match "Answer Sheet")) {
            break
        }

        if ($inSolutions) {
            if ($line -match "PRELIMINARY ROUND|VÒNG LOẠI") {
                $curRoundType = "Vòng loại"
            } elseif ($line -match "HEAT ROUND|VÒNG QUỐC GIA") {
                $curRoundType = "Vòng quốc gia"
            } elseif ($line -match "ĐỀ SỐ\s*(\d+)") {
                $curDeSo = "Đề số $($Matches[1])"
            } elseif ($line -match "^\s*(\d+)\.\s*(.*)") {
                $qNum = [int]$Matches[1]
                if ($qNum -ge 1 -and $qNum -le 30) {
                    if ($curSolQ -ne $null) {
                        $key = "$curRoundType - $curDeSo-$curSolQ"
                        $solText = $curExplLines -join "`n"
                        $ans = ""
                        if ($solText -match "Đáp\s*(?:số|án)[:\.]*\s*([A-D]|\d+)") {
                            $ans = $Matches[1].Trim()
                        }
                        $solutions[$key] = @{
                            answer = $ans
                            explanation = $solText.Trim()
                        }
                    }
                    $curSolQ = $qNum
                    $curExplLines = @()
                    if ($Matches[2] -ne "") { $curExplLines += $Matches[2] }
                } else {
                    if ($curSolQ -ne $null) { $curExplLines += $line }
                }
            } else {
                if ($curSolQ -ne $null) {
                    if (-not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC") -and -not ($line -match "^\d+$") -and -not ($line -match "KHỐI \d+")) {
                        $curExplLines += $line
                    }
                }
            }
        }
    }
    if ($curSolQ -ne $null) {
        $key = "$curRoundType - $curDeSo-$curSolQ"
        $solText = $curExplLines -join "`n"
        $ans = ""
        if ($solText -match "Đáp\s*(?:số|án)[:\.]*\s*([A-D]|\d+)") { $ans = $Matches[1].Trim() }
        $solutions[$key] = @{ answer = $ans; explanation = $solText.Trim() }
    }

    Write-Host "Grade $grade : Parsed $($solutions.Count) solutions."

    # 2. Parse Questions
    $questions = @()
    $currentQ = $null
    $inQuestions = $false
    $curRoundType = "Vòng loại"
    $curDeSo = "Đề số 1"
    $currentTopic = "Tư duy logic"

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].Trim()

        if ($line -match "PRELIMINARY ROUND" -and $i -gt 100) {
            $inQuestions = $true
            $curRoundType = "Vòng loại"
        } elseif ($inQuestions -and $line -match "HEAT ROUND") {
            $curRoundType = "Vòng quốc gia"
        } elseif ($inQuestions -and $line -match "ĐỀ SỐ\s*(\d+)") {
            $curDeSo = "Đề số $($Matches[1])"
        } elseif ($inQuestions -and $line -match "(Logical [Tt]hinking|Arithmetic|Number [Tt]heory|Geometry|Combinatorics)") {
            $currentTopic = $line
        } elseif ($line -match "LỜI GIẢI CHI TIẾT" -and $line -notmatch "\(") {
            if ($currentQ -ne $null) { $questions += $currentQ }
            break
        } elseif ($inQuestions -and $line -match "^\s*(\d+)\.\s*(.*)") {
            $qNum = [int]$Matches[1]
            if ($qNum -ge 1 -and $qNum -le 30) {
                if ($currentQ -ne $null) {
                    $questions += $currentQ
                }

                $fullRound = "$curRoundType - $curDeSo"
                $key = "$fullRound-$qNum"
                $ansInfo = $solutions[$key]
                $ansVal = ""
                $explVal = ""
                if ($ansInfo -ne $null) {
                    $ansVal = $ansInfo.answer
                    $explVal = $ansInfo.explanation
                }

                $initText = @()
                if ($Matches[2] -ne "") { $initText += $Matches[2] }

                $currentQ = [PSCustomObject]@{
                    id = "$grade-$fullRound-$qNum"
                    grade = $grade
                    exam = "TIMO"
                    round = $fullRound
                    topic = $currentTopic
                    num = $qNum
                    text = ""
                    textLines = $initText
                    options = @()
                    answer = $ansVal
                    explanation = $explVal
                    type = "mc"
                }
            }
        } elseif ($currentQ -ne $null) {
            if ($line -match "^[A-D]\.\s*") {
                $currentQ.options += $line
            } else {
                if ($line -ne "" -and -not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC") -and -not ($line -match "^\d+$") -and -not ($line -match "KHỐI \d+")) {
                    $currentQ.textLines += $line
                }
            }
        }
    }
    if ($currentQ -ne $null) { $questions += $currentQ }

    foreach ($q in $questions) {
        $q.text = ($q.textLines -join "`n").Trim()
        if ($q.options.Count -eq 0) {
            $q.type = "fill"
        }
    }

    return $questions
}

