[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

function Parse-FullTimo {
    param([string]$txtPath, [int]$grade)

    if (!(Test-Path $txtPath)) { return @() }
    $lines = Get-Content $txtPath -Encoding UTF8

    # 1. Tìm vị trí các phân đoạn
    $qStart = -1
    $solStart = -1
    $solEnd = -1

    for ($i = 200; $i -lt $lines.Count; $i++) {
        if ($qStart -eq -1 -and $lines[$i] -match "PRELIMINARY ROUND") {
            $qStart = $i
        }
        if ($solStart -eq -1 -and $lines[$i] -match "LỜI GIẢI CHI TIẾT") {
            $solStart = $i
        }
        if ($solStart -ne -1 -and $lines[$i] -match "ĐÁP ÁN THAM KHẢO") {
            $solEnd = $i
            break
        }
    }
    if ($solEnd -eq -1) { $solEnd = $lines.Count }

    Write-Host "Grade $grade : Questions [$qStart .. $solStart], Solutions [$solStart .. $solEnd]"

    # 2. Parse Solutions
    $solutions = @{}
    $curRoundType = "Vòng loại"
    $curDeSo = "Đề số 1"
    $curSolQ = $null
    $curExplLines = @()

    for ($i = $solStart; $i -lt $solEnd; $i++) {
        $line = $lines[$i].Trim()
        if ($line -match "PRELIMINARY ROUND|VÒNG LOẠI") {
            $curRoundType = "Vòng loại"
        }
        if ($line -match "HEAT ROUND|VÒNG QUỐC GIA") {
            $curRoundType = "Vòng quốc gia"
        }
        if ($line -match "ĐỀ SỐ\s*(\d+)") {
            $curDeSo = "Đề số $($Matches[1])"
        }
        if ($line -match "^\s*(\d+)\.\s*(.*)") {
            $qNum = [int]$Matches[1]
            if ($qNum -ge 1 -and $qNum -le 30) {
                if ($curSolQ -ne $null) {
                    $key = "$curRoundType - $curDeSo-$curSolQ"
                    $solText = $curExplLines -join "`n"
                    $ans = ""
                    if ($solText -match "Đáp\s*(?:số|án)[:\.]*\s*([A-D]|\d+)") {
                        $ans = $Matches[1].Trim()
                    }
                    $solutions[$key] = @{
                        answer = $ans
                        explanation = $solText.Trim()
                    }
                }
                $curSolQ = $qNum
                $curExplLines = @()
                if ($Matches[2] -ne "") { $curExplLines += $Matches[2] }
            } else {
                if ($curSolQ -ne $null) { $curExplLines += $line }
            }
        } else {
            if ($curSolQ -ne $null) {
                if (-not ($line -match "FERMAT Education") -and -not ($line -match "KỲ THI OLYMPIC") -and -not ($line -match "^\d+$") -and -not ($line -match "KHỐI \d+")) {
                    $curExplLines += $line
                }
            }
        }
    }
    if ($curSolQ -ne $null) {
        $key = "$curRoundType - $curDeSo-$curSolQ"
        $solText = $curExplLines -join "`n"
        $ans = ""
        if ($solText -match "Đáp\s*(?:số|án)[:\.]*\s*([A-D]|\d+)") { $ans = $Matches[1].Trim() }
        $solutions[$key] = @{ answer = $ans; explanation = $solText.Trim() }
    }

    Write-Host "Grade $grade : Total $($solutions.Count) solutions parsed."

    # 3. Parse Questions
    $questions = @()
    $currentQ = $null
    $curRoundType = "Vòng loại"
    $curDeSo = "Đề số 1"
    $currentTopic = "Tư duy logic"

    for ($i = $qStart; $i -lt $solStart; $i++) {
        $line = $lines[$i].Trim()

        if ($line -match "PRELIMINARY ROUND") {
            $curRoundType = "Vòng loại"
        }
        if ($line -match "HEAT ROUND") {
            $curRoundType = "Vòng quốc gia"
        }
        if ($line -match "ĐỀ SỐ\s*(\d+)") {
            $curDeSo = "Đề số $($Matches[1])"
        }
        if ($line -match "(Logical [Tt]hinking|Arithmetic|Number [Tt]heory|Geometry|Combinatorics)") {
            $currentTopic = $line
        }

        if ($line -match "^\s*(\d+)\.\s*(.*)") {
            $qNum = [int]$Matches[1]
            if ($qNum -ge 1 -and $qNum -le 30) {
                if ($currentQ -ne $null) {
                    $questions += $currentQ
                }

                $fullRound = "$curRoundType - $curDeSo"
                $key = "$fullRound-$qNum"
                $ansInfo = $solutions[$key]
                $ansVal = ""
                $explVal = ""
                if ($ansInfo -ne $null) {
                    $ansVal = $ansInfo.answer
                    $explVal = $ansInfo.explanation
                }

                $initText = @()
                if ($Matches[2] -ne "") { $initText += $Matches[2] }

                $currentQ = [PSCustomObject]@{
                    id = "$grade-$fullRound-$qNum"
                    grade = $grade
                    exam = "TIMO"
                    round = $fullRound
                    topic = $currentTopic
                    num = $qNum
                    text = ""
                    textLines = $initText
                    options = @()
                    answer = $ansVal
                    explanation = $explVal
                    type = "mc"
                }
            }
        } elseif ($currentQ -ne $null) {
            if ($line -match "^[A-D]\.\s*") {
