                $optD = $Matches[4].Trim()
                if ($optA.Length -gt 0 -and $optB.Length -gt 0 -and $optC.Length -gt 0 -and $optD.Length -gt 0) {
                    $currentQ.options = @("A. $optA", "B. $optB", "C. $optC", "D. $optD")
                }
            }
