            elseif ($rawLine -match "A\.\s*(.+?)\s{2,}B\.\s*(.+)") {
                $optA = $Matches[1].Trim()
                $optB = $Matches[2].Trim()
                if ($optA.Length -gt 0 -and $optB.Length -gt 0) {
                    $currentQ.options += "A. $optA"
                    $currentQ.options += "B. $optB"
                }
            }
            # Trường hợp 3: Dòng chứa C. ... D. ... (2 phương án sau)
            elseif ($rawLine -match "C\.\s*(.+?)\s{2,}D\.\s*(.+)") {
                $optC = $Matches[1].Trim()
                $optD = $Matches[2].Trim()
                if ($optC.Length -gt 0 -and $optD.Length -gt 0) {
                    $currentQ.options += "C. $optC"
                    $currentQ.options += "D. $optD"
                }
            }
            # Trường hợp 4: Từng phương án riêng lẻ trên 1 dòng
            elseif ($line -match "^[A-D]\.\s*(.+)") {
                $optVal = $Matches[1].Trim()
                if ($optVal.Length -gt 0) {
                    $currentQ.options += $line
                }
            }
            else {
                # Không phải đáp án -> Thuộc về đề bài
                if ($line -ne "" -and -not ($line -match "FERMAT Education") -and -not ($line -match "OLYMPIC") -and -not ($line -match "^\d+$") -and -not ($line -match "KH.*I")) {
                    # Giữ nguyên thụt dòng nếu là phép tính cột dọc (chứa + hoặc - hoặc A hoặc số)
                    if ($rawLine -match "^\s{10,}[\+\-]?\s*[A-Z0-9\s]{2,}$") {
                        $currentQ.textLines += $rawLine
                    } else {
                        $currentQ.textLines += $line
                    }
                }
            }
        }
    }
    if ($currentQ -ne $null) { $questions += $currentQ }

    # Hoàn thiện & chuẩn hóa từng câu
    $cleanQuestions = @()
    foreach ($q in $questions) {
        $q.text = ($q.textLines -join "`n").Trim()

        # Nếu có đủ 4 lựa chọn A, B, C, D
        if ($q.options.Count -eq 4) {
            $q.type = "mc"
        } else {
