            $q.options = @()
            $q.type = "fill"
        }

        # LỌC CHẤT LƯỢNG CAO:
        # 1. Đề bài phải có nội dung rõ ràng (> 15 ký tự)
        # 2. Phải có đáp án đúng
        # 3. Không bị câu hỏi rỗng hình ảnh (như "Cho hai chiếc cân dưới đây..." mà không có chữ)
        $isMissingImage = ($q.text -match "dưới đây|below|theo hình|hình vẽ|pattern below") -and ($q.textLines.Count -le 3) -and ($q.type -eq "mc") -and ($q.options.Count -eq 0)

        if ($q.text.Length -ge 15 -and $q.answer -ne "" -and -not $isMissingImage) {
            $cleanQuestions += $q
        }
    }

    return $cleanQuestions
}

