                if ($rawLine -match "^\s{15,}[\+\-]?\s*[A-Z0-9\s]{2,}$") {
                    $currentQ.textLines += $rawLine
                } else {
                    $currentQ.textLines += $line
                }
            }
        }
    }
    if ($currentQ -ne $null) { $questions += $currentQ }

    # Lọc chất lượng cao
    $cleanQuestions = @()
    foreach ($q in $questions) {
        $q.text = ($q.textLines -join "`n").Trim()

        if ($q.options.Count -eq 4) {
