        } else {
            $q.options = @()
            $q.type = "fill"
        }

        # Chỉ giữ câu chất lượng: có đề rõ, có đáp án
        if ($q.text.Length -ge 15 -and $q.answer -ne "") {
            $cleanQuestions += $q
        }
    }

    return $cleanQuestions
}

