// ==========================================================
// HỆ THỐNG AI SINH ĐỀ TỰ ĐỘNG THÔNG MINH (DYNAMIC GENERATOR)
// ==========================================================
function generateDynamicOlympicQuestion(grade, examType) {
  const g = parseInt(grade) || 1;
  const examName = examType || 'Kangaroo';

  // Dạng 1: Phép tính chuỗi số thông minh (Lớp 1-2)
  if (g <= 2) {
    const a = Math.floor(Math.random() * 8) + 2;
    const b = Math.floor(Math.random() * 8) + 2;
    const c = Math.floor(Math.random() * 8) + 2;
    const ans = a + b - c;
    if (ans > 0) {
      const wrongs = [ans + 1, ans - 1, ans + 2].sort(() => Math.random() - 0.5);
      const opts = [ans, ...wrongs].sort(() => Math.random() - 0.5);
      const letters = ['A', 'B', 'C', 'D'];
      const correctLetter = letters[opts.indexOf(ans)];
      return {
        id: `AI-${Date.now()}-${Math.random()}`,
        exam: examName,
        grade: g,
        round: `${examName} - Đề Tự Sinh Đổi Mới`,
        topic: "Tính nhẩm nhanh Olympic",
        type: "mc",
        text: `Find the value of: ${a} + ${b} - ${c}.\nTìm giá trị của biểu thức: ${a} + ${b} - ${c}.`,
        options: opts.map((val, idx) => `${letters[idx]}. ${val}`),
        answer: correctLetter,
        explanation: `Ta tính lần lượt: ${a} + ${b} = ${a+b}; ${a+b} - ${c} = ${ans}.\nĐáp số: ${correctLetter}.`
      };
    }
  }

  // Dạng 2: Bài toán chân gà, chân thỏ hoặc xe cộ (Lớp 2-3)
  if (g === 2 || g === 3) {
    const num = Math.floor(Math.random() * 6) + 3; // 3 đến 8 con
    const ans = num * 4;
    const opts = [ans - 4, ans, ans + 4, ans + 2].sort(() => Math.random() - 0.5);
    const letters = ['A', 'B', 'C', 'D'];
    const correctLetter = letters[opts.indexOf(ans)];
    return {
      id: `AI-${Date.now()}-${Math.random()}`,
      exam: examName,
      grade: g,
      round: `${examName} - Đề Tự Sinh Đổi Mới`,
      topic: "Toán đếm số lượng",
      type: "mc",
      text: `There are ${num} cars in the parking lot. Each car has 4 wheels. How many wheels are there in total?\nCó ${num} chiếc ô tô trong bãi đỗ xe. Mỗi ô tô có 4 bánh xe. Hỏi có tất cả bao nhiêu bánh xe?`,
      options: opts.map((val, idx) => `${letters[idx]}. ${val}`),
      answer: correctLetter,
      explanation: `Mỗi chiếc ô tô có 4 bánh xe. Có ${num} chiếc xe thì tổng số bánh là: ${num} x 4 = ${ans} (bánh xe).\nĐáp số: ${correctLetter}.`
    };
  }

  // Dạng 3: Bài toán chu vi / diện tích hình học (Lớp 3-5)
  if (g >= 3) {
    const side = Math.floor(Math.random() * 8) + 4; // Cạnh 4 đến 11
    const perimeter = side * 4;
    const area = side * side;
    const isPerimeter = Math.random() > 0.5;
    const ans = isPerimeter ? perimeter : area;
    const opts = [ans - 2, ans, ans + 4, ans + 6].sort(() => Math.random() - 0.5);
    const letters = ['A', 'B', 'C', 'D'];
    const correctLetter = letters[opts.indexOf(ans)];
    return {
      id: `AI-${Date.now()}-${Math.random()}`,
      exam: examName,
      grade: g,
      round: `${examName} - Đề Tự Sinh Đổi Mới`,
      topic: isPerimeter ? "Chu vi hình vuông" : "Diện tích hình vuông",
      type: "mc",
      text: isPerimeter 
        ? `A square has a side length of ${side} cm. What is its perimeter?\nMột hình vuông có cạnh dài ${side} cm. Chu vi của hình vuông đó là bao nhiêu cm?`
        : `A square has a side length of ${side} cm. What is its area?\nMột hình vuông có cạnh dài ${side} cm. Diện tích của hình vuông đó là bao nhiêu cm²?`,
      options: opts.map((val, idx) => `${letters[idx]}. ${val} ${isPerimeter ? 'cm' : 'cm²'}`),
      answer: correctLetter,
      explanation: isPerimeter 
        ? `Chu vi hình vuông bằng cạnh nhân 4: ${side} x 4 = ${ans} (cm).\nĐáp số: ${correctLetter}.`
        : `Diện tích hình vuông bằng cạnh nhân cạnh: ${side} x ${side} = ${ans} (cm²).\nĐáp số: ${correctLetter}.`
    };
  }

  // Fallback
  return EXTRA_EXAMS_DB.grade1[0];
}

