    return Array.from(rounds);
  } else if (e === 'TIMO') {
    if (typeof TIMO_DB === 'undefined' || !TIMO_DB['grade' + grade]) return [];
    const list = TIMO_DB['grade' + grade];
    const rounds = new Set();
