// HÀM FORMAT NỘI DUNG ĐỀ THI ĐẸP MẮT (NỐI LIỀN DÒNG BỊ NGẮT CỦA PDF)
function formatQuestionText(rawText) {
  if (!rawText) return '';
  const cleaned = cleanMathSymbols(rawText);
  const rawLines = cleaned.split('\n');

  let mergedParagraphs = [];
  let currentParagraph = '';
  let mathLines = [];

  for (let i = 0; i < rawLines.length; i++) {
    const line = rawLines[i].trim();
    if (!line) continue;

    // Đặt tính cột dọc độc lập
    const isPureMathLine = line.match(/^[\+\-]?\s*[A-Z0-9\s]{2,6}$/i) && !line.match(/[a-z]{3,}|giá trị|phép|tìm|value|find/i);

    if (isPureMathLine) {
      if (currentParagraph) {
        mergedParagraphs.push(currentParagraph.trim());
        currentParagraph = '';
      }
      mathLines.push(line);
    } else {
      if (mathLines.length > 0) {
        mergedParagraphs.push({ type: 'math', lines: mathLines });
        mathLines = [];
      }

      // Kiểm tra xem dòng này có phải là mở đầu của một đoạn mới không
      // (Ví dụ: dòng tiếng Việt mới, hoặc bắt đầu bằng dấu gạch đầu dòng, a), b)...)
      const isNewSection = line.match(/^[a-d]\)|^[0-9]+\.|^Tìm |^Cho |^Biết |^Tính |^Hỏi |^Định nghĩa|^Mark:|^Note:|^Value:/i);

      if (!currentParagraph) {
        currentParagraph = line;
      } else if (isNewSection) {
        mergedParagraphs.push(currentParagraph.trim());
        currentParagraph = line;
      } else {
        // Nối tiếp vào dòng trước bằng khoảng trắng (loại bỏ lỗi ngắt dòng của PDF)
        currentParagraph += ' ' + line;
      }
    }
  }
  if (mathLines.length > 0) {
    mergedParagraphs.push({ type: 'math', lines: mathLines });
  }
  if (currentParagraph) {
    mergedParagraphs.push(currentParagraph.trim());
  }

  // Render các đoạn văn bản đã được nối liền mượt mà
  let html = '';
  for (const p of mergedParagraphs) {
    if (typeof p === 'object' && p.type === 'math') {
      html += renderMathColumn(p.lines);
    } else {
      const isVi = p.match(/[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i);
      html += `<div class="question-line ${isVi ? 'question-vietnamese' : ''}">${p}</div>`;
    }
  }
  return html;
}

