// HÀM FORMAT NỘI DUNG ĐỀ THI ĐẸP MẮT (CHỐNG VỠ FONT VÀ LỖI KÝ HIỆU)
function formatQuestionText(rawText) {
  if (!rawText) return '';
  const cleaned = cleanMathSymbols(rawText);
  const lines = cleaned.split('\n');
  let html = '';
  let mathLines = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Chỉ coi là đặt tính cột dọc khi dòng ĐỘC LẬP CHỈ CHỨA SỐ VÀ DẤU CỘNG/TRỪ NGẮN (<= 12 ký tự)
    // Ví dụ: "+ 4 A" hoặc "3 5" hoặc "A 3", KHÔNG PHẢI là câu văn!
    const isPureMathLine = line.match(/^[\+\-]?\s*[A-Z0-9\s]{2,6}$/i) && !line.match(/[a-z]{3,}|giá trị|phép|tìm|value|find/i);

    if (isPureMathLine) {
      mathLines.push(line);
    } else {
      if (mathLines.length > 0) {
        html += renderMathColumn(mathLines);
        mathLines = [];
      }
      const isVi = line.match(/[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i);
      html += `<div class="question-line ${isVi ? 'question-vietnamese' : ''}">${line}</div>`;
    }
  }
  if (mathLines.length > 0) {
    html += renderMathColumn(mathLines);
  }
  return html;
}

