};

function isUserExpired(user) {
  if (!user || user.role === 'admin') return false;
  if (!user.expireAt || user.expireAt === 'unlimited') return false;
  const exp = new Date(user.expireAt).getTime();
  return Date.now() > exp;
}

function getExpiryInfo(user) {
  if (!user || user.role === 'admin') {
    return { status: 'unlimited', label: '♾️ Vĩnh viễn (Quản trị)', badgeClass: 'badge-unlimited' };
  }
  if (!user.expireAt || user.expireAt === 'unlimited') {
    return { status: 'unlimited', label: '♾️ Vĩnh viễn (Chính thức)', badgeClass: 'badge-unlimited' };
  }
  const exp = new Date(user.expireAt).getTime();
  const diff = exp - Date.now();
  const dateObj = new Date(user.expireAt);
  const dateStr = `${String(dateObj.getDate()).padStart(2, '0')}/${String(dateObj.getMonth() + 1).padStart(2, '0')}/${dateObj.getFullYear()}`;

  if (diff <= 0) {
    return { status: 'expired', label: `🔴 ĐÃ HẾT HẠN (${dateStr})`, dateStr, isExpired: true, badgeClass: 'badge-expired' };
  }
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));
  const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  if (days === 0) {
    return { status: 'warning', label: `🟡 Còn ${hours} giờ (Hôm nay: ${dateStr})`, days, hours, dateStr, badgeClass: 'badge-warning' };
  } else if (days <= 3) {
    return { status: 'warning', label: `🟡 Còn ${days} ngày (Hết hạn ${dateStr})`, days, dateStr, badgeClass: 'badge-warning' };
  } else {
    return { status: 'active', label: `🟢 Còn ${days} ngày (Đến ${dateStr})`, days, dateStr, badgeClass: 'badge-active' };
  }
}

function userCanAccessGrade(user, gradeId) {
  if (!user || user.role === 'admin') return true;
  if (!user.allowedGrades || user.allowedGrades.includes('all')) return true;
  return user.allowedGrades.includes(Number(gradeId)) || user.allowedGrades.includes(String(gradeId));
}

function userCanAccessExam(user, examId) {
  if (!user || user.role === 'admin') return true;
  if (!user.allowedExams || user.allowedExams.includes('all')) return true;
  return user.allowedExams.includes(examId);
}

