// Verify the complete new script section
const fullCode = `
    function render() {
      const app = document.getElementById('app');

      // BẮT BUỘC ĐĂNG NHẬP
      if (!state.currentUser) {
        renderLogin(app);
        return;
      }

      // Luôn đồng bộ dữ liệu mới nhất của người dùng từ cơ sở dữ liệu
      const users = getUsersDB();
      const latestUser = users.find(u => u.username.toLowerCase() === state.currentUser.username.toLowerCase());
      if (!latestUser) {
        state.currentUser = null;
        localStorage.removeItem('mathquiz_current_user');
        renderLogin(app);
        return;
      }
      state.currentUser = latestUser;

      // Kiểm tra hạn sử dụng
      if (isUserExpired(state.currentUser)) {
        const expInfo = getExpiryInfo(state.currentUser);
        alert('⛔ TÀI KHOẢN ĐÃ HẾT HẠN DÙNG THỬ!\\n\\nChào bé ' + state.currentUser.name + ', tài khoản của con đã hết hạn dùng thử vào ngày ' + expInfo.dateStr + '.\\n\\nBa mẹ vui lòng liên hệ Thầy Nguyễn Đình Chinh (Zalo/Hotline: 0941.492.468) để gia hạn khóa học cho con nhé! ❤️');
        state.currentUser = null;
        localStorage.removeItem('mathquiz_current_user');
        renderLogin(app);
        return;
      }

      // Tự động điều chỉnh khối lớp & kỳ thi nếu khối lớp hiện tại không được cấp quyền
      if (!userCanAccessGrade(state.currentUser, state.selectedGrade)) {
        const firstAllowedGrade = CONFIG.grades.find(g => userCanAccessGrade(state.currentUser, g.id));
        if (firstAllowedGrade) state.selectedGrade = firstAllowedGrade.id;
      }
      if (!userCanAccessExam(state.currentUser, state.selectedExam)) {
        const firstAllowedExam = CONFIG.exams.find(e => userCanAccessExam(state.currentUser, e.id));
        if (firstAllowedExam) state.selectedExam = firstAllowedExam.id;
      }

      if (state.screen === 'admin') renderAdmin(app);
      else if (state.screen === 'home') renderHome(app);
      else if (state.screen === 'quiz') renderQuiz(app);
      else if (state.screen === 'results') renderResults(app);
      else if (state.screen === 'history') renderHistory(app);
    }

    // MÀN HÌNH ĐĂNG NHẬP BẢO VỆ
    function renderLogin(app) {
      app.innerHTML = \`
        <div style="max-width:440px;margin:40px auto;text-align:center">
          <div class="header-logo">🔐</div>
          <h2 style="font-size:2em;font-weight:900;color:#1E293B;margin-bottom:6px">Đăng Nhập Hệ Thống</h2>
          <p style="color:var(--text-muted);margin-bottom:24px;font-weight:700">
            Hệ thống học tập nội bộ Thầy Nguyễn Đình Chinh.<br>Vui lòng nhập tài khoản được cấp để vào học.
          </p>

          <div class="card" style="text-align:left;box-shadow:var(--shadow-lg)">
            <div style="margin-bottom:16px">
              <label style="font-weight:800;display:block;margin-bottom:6px">👤 Tên đăng nhập:</label>
              <input type="text" class="name-input" id="loginUser" placeholder="Ví dụ: hocsinh1..." autofocus>
            </div>

            <div style="margin-bottom:20px">
              <label style="font-weight:800;display:block;margin-bottom:6px">🔑 Mật khẩu:</label>
              <input type="password" class="name-input" id="loginPass" placeholder="Nhập mật khẩu...">
            </div>

            <div id="loginError" style="color:#DC2626;font-weight:800;margin-bottom:14px;display:none;font-size:0.95em">
              ❌ Sai tên đăng nhập hoặc mật khẩu! Vui lòng thử lại.
            </div>

            <button class="btn btn-primary btn-lg btn-block" onclick="handleLogin()">
              🚀 ĐĂNG NHẬP VÀO HỌC
            </button>
          </div>

          <div style="margin-top:20px;font-size:0.9em;color:#64748B;font-weight:700">
            Chưa có tài khoản? Liên hệ Thầy Chinh qua Zalo:<br>
            <a href="https://zalo.me/0941492468" target="_blank" style="color:var(--primary);font-weight:900;font-size:1.1em">
              📞 0941.492.468
            </a>
          </div>
        </div>
      \`;

      // Hỗ trợ bấm phím Enter để đăng nhập
      document.getElementById('loginPass').addEventListener('keypress', (e) => {
        if (e.key === 'Enter') handleLogin();
      });
      document.getElementById('loginUser').addEventListener('keypress', (e) => {
        if (e.key === 'Enter') handleLogin();
      });
    }

    function handleLogin() {
      const u = document.getElementById('loginUser').value.trim();
      const p = document.getElementById('loginPass').value.trim();
      const users = getUsersDB();
      const found = users.find(x => x.username.toLowerCase() === u.toLowerCase() && x.pass === p);

      if (found) {
        if (isUserExpired(found)) {
          const expInfo = getExpiryInfo(found);
          alert('⛔ TÀI KHOẢN ĐÃ HẾT HẠN DÙNG THỬ!\\n\\nChào bé ' + found.name + ', tài khoản của con đã hết hạn vào ngày ' + expInfo.dateStr + '.\\n\\nBa mẹ vui lòng liên hệ Thầy Nguyễn Đình Chinh (Zalo/Hotline: 0941.492.468) để gia hạn khóa học cho con nhé! ❤️');
          return;
        }
        state.currentUser = found;
        state.playerName = found.name;
        localStorage.setItem('mathquiz_current_user', JSON.stringify(found));
        localStorage.setItem('mathquiz_name', found.name);
        state.screen = 'home';
        render();
      } else {
        const err = document.getElementById('loginError');
        if (err) err.style.display = 'block';
      }
    }

    function handleLogout() {
      if (confirm('Bạn có chắc chắn muốn đăng xuất không?')) {
        state.currentUser = null;
        localStorage.removeItem('mathquiz_current_user');
        state.screen = 'home';
        render();
      }
    }
`;
