// QUẢN LÝ FORM CẤP MỚI TÀI KHOẢN
function toggleNewUserAllGrades() {
  const all = document.getElementById('newAllGrades');
  const isChecked = all.checked;
  for (let i = 1; i <= 5; i++) {
    const el = document.getElementById('newGrade_' + i);
    if (el) el.checked = isChecked;
  }
}

function toggleNewUserAllExams() {
  const all = document.getElementById('newAllExams');
  const isChecked = all.checked;
  ['TIMO', 'Kangaroo', 'ASMO', 'SPECIAL_G4'].forEach(id => {
    const el = document.getElementById('newExam_' + id);
    if (el) el.checked = isChecked;
  });
}

function setNewUserExpiryPreset(days) {
  const dateInput = document.getElementById('newUserExpireDate');
  const unlimCheck = document.getElementById('newUserUnlimited');
  document.querySelectorAll('#newUserPresets .preset-btn').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById('preset_btn_' + days);
  if (activeBtn) activeBtn.classList.add('active');

  if (days === 'unlimited') {
    if (unlimCheck) unlimCheck.checked = true;
    if (dateInput) { dateInput.disabled = true; dateInput.value = ''; }
  } else {
    if (unlimCheck) unlimCheck.checked = false;
    const target = new Date(Date.now() + days * 86400000);
    const yyyy = target.getFullYear();
    const mm = String(target.getMonth() + 1).padStart(2, '0');
    const dd = String(target.getDate()).padStart(2, '0');
    if (dateInput) {
      dateInput.disabled = false;
      dateInput.value = `${yyyy}-${mm}-${dd}`;
    }
  }
}

function onNewUserUnlimitedChange() {
  const unlimCheck = document.getElementById('newUserUnlimited');
  const dateInput = document.getElementById('newUserExpireDate');
  if (unlimCheck.checked) {
    dateInput.disabled = true;
    dateInput.value = '';
    document.querySelectorAll('#newUserPresets .preset-btn').forEach(btn => btn.classList.remove('active'));
    const btn = document.getElementById('preset_btn_unlimited');
    if (btn) btn.classList.add('active');
  } else {
    dateInput.disabled = false;
    setNewUserExpiryPreset(7);
  }
}

function addNewUser() {
  const name = document.getElementById('newUserName').value.trim();
  const username = document.getElementById('newUserLogin').value.trim().toLowerCase();
  const pass = document.getElementById('newUserPass').value.trim();

  if (!name || !username || !pass) {
    alert('Vui lòng điền đủ Họ tên bé, Tên đăng nhập và Mật khẩu!');
    return;
  }

  const users = getUsersDB();
  if (users.find(u => u.username.toLowerCase() === username)) {
    alert('Tên đăng nhập "' + username + '" đã tồn tại! Vui lòng chọn tên khác.');
    return;
  }

  // Đọc quyền khối lớp
  let allowedGrades = [];
  const allGrades = document.getElementById('newAllGrades').checked;
  if (allGrades) {
    allowedGrades = ['all'];
  } else {
    for (let i = 1; i <= 5; i++) {
      const el = document.getElementById('newGrade_' + i);
      if (el && el.checked) allowedGrades.push(i);
    }
    if (allowedGrades.length === 5) allowedGrades = ['all'];
  }

  if (allowedGrades.length === 0) {
    alert('Vui lòng chọn ít nhất 1 Khối lớp cho bé!');
    return;
  }

  // Đọc quyền kỳ thi
  let allowedExams = [];
  const allExams = document.getElementById('newAllExams').checked;
  if (allExams) {
    allowedExams = ['all'];
  } else {
    ['TIMO', 'Kangaroo', 'ASMO', 'SPECIAL_G4'].forEach(id => {
      const el = document.getElementById('newExam_' + id);
      if (el && el.checked) allowedExams.push(id);
    });
    if (allowedExams.length === 4) allowedExams = ['all'];
  }

  if (allowedExams.length === 0) {
    alert('Vui lòng chọn ít nhất 1 Kỳ thi / Môn học cho bé!');
    return;
  }

  // Đọc thời hạn sử dụng
  let expireAt = 'unlimited';
  const isUnlimited = document.getElementById('newUserUnlimited').checked;
  if (!isUnlimited) {
    const dateVal = document.getElementById('newUserExpireDate').value;
    if (!dateVal) {
      alert('Vui lòng chọn ngày hết hạn hoặc bấm chọn Vĩnh viễn!');
      return;
    }
    expireAt = dateVal + 'T23:59:59';
  }

  const newUser = {
    username,
    pass,
    name,
    role: 'student',
    allowedGrades,
    allowedExams,
    expireAt,
    createdAt: new Date().toISOString()
  };

  users.push(newUser);
  saveUsersDB(users);
  alert('🎉 ĐÃ CẤP TÀI KHOẢN THÀNH CÔNG CHO BÉ: ' + name + '\n' +
        '• Tên đăng nhập: ' + username + '\n' +
        '• Mật khẩu: ' + pass + '\n' +
        '• Khối lớp: ' + (allowedGrades.includes('all') ? 'Tất cả (Lớp 1-5)' : allowedGrades.join(', ')) + '\n' +
        '• Môn thi: ' + (allowedExams.includes('all') ? 'Tất cả môn' : allowedExams.join(', ')) + '\n' +
        '• Hạn dùng: ' + (expireAt === 'unlimited' ? 'Vĩnh viễn' : getExpiryInfo(newUser).dateStr));
  render();
}

function deleteUser(username) {
  if (confirm('Bạn có chắc chắn muốn xóa tài khoản "' + username + '" không?\nDữ liệu học sinh này sẽ bị xóa khỏi hệ thống.')) {
    let users = getUsersDB();
    users = users.filter(u => u.username !== username);
    saveUsersDB(users);
    if (state.currentUser && state.currentUser.username === username) {
      state.currentUser = null;
      localStorage.removeItem('mathquiz_current_user');
    }
    render();
  }
}

// SAO LƯU & PHỤC HỒI DANH SÁCH
function exportUsersBackup() {
  const users = getUsersDB();
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(users, null, 2));
  const a = document.createElement('a');
  a.setAttribute("href", dataStr);
  a.setAttribute("download", "danh-sach-hoc-sinh-thay-chinh-" + new Date().toISOString().slice(0,10) + ".json");
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function triggerImportUsers() {
  const input = document.getElementById('importUsersInput');
  if (input) input.click();
}

function handleImportUsers(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const imported = JSON.parse(e.target.result);
      if (Array.isArray(imported)) {
        if (confirm('Tìm thấy ' + imported.length + ' tài khoản trong file sao lưu.\nBạn có muốn nạp và cập nhật danh sách học sinh này không?')) {
          saveUsersDB(imported);
          alert('✅ Đã phục hồi danh sách học sinh thành công!');
          render();
        }
      } else {
        alert('File sao lưu không đúng định dạng!');
      }
    } catch (err) {
      alert('Lỗi đọc file: ' + err.message);
    }
  };
  reader.readAsText(file);
}

