function saveEditUser(username) {
  const users = getUsersDB();
  const user = users.find(u => u.username === username);
  if (!user) return;

  const name = document.getElementById('editUserName').value.trim();
  const pass = document.getElementById('editUserPass').value.trim();

  if (!name || !pass) {
    alert('Họ tên và Mật khẩu không được để trống!');
    return;
  }

  // Khối lớp
  let allowedGrades = [];
  const allGrades = document.getElementById('editAllGrades').checked;
  if (allGrades) {
    allowedGrades = ['all'];
  } else {
    for (let i = 1; i <= 5; i++) {
      const el = document.getElementById('editGrade_' + i);
      if (el && el.checked) allowedGrades.push(i);
    }
    if (allowedGrades.length === 5) allowedGrades = ['all'];
  }

  if (allowedGrades.length === 0) {
    alert('Vui lòng chọn ít nhất 1 Khối lớp!');
    return;
  }

  // Kỳ thi
  let allowedExams = [];
  const allExams = document.getElementById('editAllExams').checked;
  if (allExams) {
    allowedExams = ['all'];
  } else {
    ['TIMO', 'Kangaroo', 'ASMO', 'SPECIAL_G4'].forEach(id => {
      const el = document.getElementById('editExam_' + id);
      if (el && el.checked) allowedExams.push(id);
    });
    if (allowedExams.length === 4) allowedExams = ['all'];
  }

  if (allowedExams.length === 0) {
    alert('Vui lòng chọn ít nhất 1 Kỳ thi / Môn học!');
    return;
  }

  // Hạn dùng
  let expireAt = 'unlimited';
  const isUnlimited = document.getElementById('editUserUnlimited').checked;
  if (!isUnlimited) {
    const dateVal = document.getElementById('editUserExpireDate').value;
    if (!dateVal) {
      alert('Vui lòng chọn ngày hết hạn hoặc bấm chọn Vĩnh viễn!');
      return;
    }
    expireAt = dateVal + 'T23:59:59';
  }

  user.name = name;
  user.pass = pass;
  user.allowedGrades = allowedGrades;
  user.allowedExams = allowedExams;
  user.expireAt = expireAt;

  saveUsersDB(users);
  if (state.currentUser && state.currentUser.username === username) {
    state.currentUser = user;
    localStorage.setItem('mathquiz_current_user', JSON.stringify(user));
    localStorage.setItem('mathquiz_name', user.name);
  }

  alert('✅ ĐÃ CẬP NHẬT THÀNH CÔNG CHO HỌC SINH: ' + name);
  state.editingUser = null;
  render();
}

function renderEditUserModalHtml(user) {
  if (!user) return '';
  const exp = getExpiryInfo(user);
  const isUnlimited = !user.expireAt || user.expireAt === 'unlimited';
  let dateVal = '';
  if (!isUnlimited && user.expireAt) {
    dateVal = user.expireAt.slice(0, 10);
  }

  const allGradesChecked = !user.allowedGrades || user.allowedGrades.includes('all');
  const allExamsChecked = !user.allowedExams || user.allowedExams.includes('all');

  return `
    <div class="modal-overlay" onclick="if(event.target === this) closeEditUserModal()">
      <div class="modal-box">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
