          <input type="text" class="name-input" id="newUserName" placeholder="Ví dụ: Nguyễn Gia Huy">
        </div>
        <div>
          <label style="font-weight:800;font-size:0.9em;display:block;margin-bottom:4px">Tên đăng nhập (viết liền):</label>
          <input type="text" class="name-input" id="newUserLogin" placeholder="Ví dụ: giahuy">
