          <input type="text" class="name-input" id="newUserPass" placeholder="Ví dụ: 123456" value="123456">
        </div>
        <button class="btn btn-success" style="height:56px" onclick="addNewUser()">
          ➕ Thêm
        </button>
      </div>
    </div>

    <div class="card">
      <div class="card-title">📋 Danh Sách Tài Khoản Đang Hoạt Động (${users.length} tài khoản)</div>
      <table style="width:100%;border-collapse:collapse">
        <thead>
          <tr style="text-align:left;border-bottom:2px solid var(--border)">
            <th style="padding:10px">Họ & Tên</th>
            <th style="padding:10px">Tên Đăng Nhập</th>
