              <td style="padding:12px;font-weight:800">${u.name}</td>
              <td style="padding:12px;color:var(--primary);font-weight:700">${u.username}</td>
              <td style="padding:12px;font-family:monospace;font-weight:800">${u.pass}</td>
              <td style="padding:12px"><span style="background:${u.role==='admin'?'#F59E0B':'#E2E8F0'};padding:2px 8px;border-radius:10px;font-size:0.85em;font-weight:800">${u.role}</span></td>
              <td style="padding:12px;text-align:center">
                ${u.role !== 'admin' ? `
                  <button class="btn btn-outline" style="padding:6px 12px;font-size:0.85em;color:#EF4444;border-color:#EF4444" onclick="deleteUser('${u.username}')">
                    🗑️ Xóa
                  </button>
                ` : '<span style="color:#94A3B8;font-size:0.85em">Mặc định</span>'}
              </td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function addNewUser() {
  const name = document.getElementById('newUserName').value.trim();
  const username = document.getElementById('newUserLogin').value.trim().toLowerCase();
  const pass = document.getElementById('newUserPass').value.trim();

  if (!name || !username || !pass) {
    alert('Vui lòng điền đủ Họ tên, Tên đăng nhập và Mật khẩu!');
    return;
  }

  const users = getUsersDB();
  if (users.find(u => u.username.toLowerCase() === username)) {
    alert('Tên đăng nhập này đã tồn tại! Vui lòng chọn tên khác.');
    return;
  }

  users.push({ username, pass, name, role: 'student' });
  saveUsersDB(users);
  alert(`Đã cấp tài khoản thành công cho bé: ${name}!\nTài khoản: ${username} | Mật khẩu: ${pass}`);
  render();
}

function deleteUser(username) {
  if (confirm(`Bạn có chắc muốn xóa tài khoản "${username}" không?`)) {
    let users = getUsersDB();
    users = users.filter(u => u.username !== username);
    saveUsersDB(users);
    render();
  }
}

