          allowedGrades: ['all'],
          allowedExams: ['TIMO', 'Kangaroo'],
          expireAt: '2026-11-10T23:59:59',
          createdAt: '2026-11-01'
        }
      ];

  let users = [...baseDefaultUsers];
  const saved = localStorage.getItem('mathquiz_users');
  if (saved) {
    try {
      const localUsers = JSON.parse(saved);
      if (Array.isArray(localUsers)) {
        // Hợp nhất dữ liệu: Đảm bảo tài khoản mới tạo ở local hay server đều không bị mất
        localUsers.forEach(lu => {
          const idx = users.findIndex(u => u.username.toLowerCase() === lu.username.toLowerCase());
          if (idx >= 0) {
            users[idx] = lu;
          } else {
            users.push(lu);
          }
        });
      }
    } catch(e) {}
  }

  // Tự động chuẩn hóa quyền & hạn dùng
  users = users.map(u => {
    if (!u.allowedGrades) u.allowedGrades = ['all'];
    if (!u.allowedExams) u.allowedExams = ['all'];
    if (u.expireAt === undefined) u.expireAt = 'unlimited';
    return u;
  });

  localStorage.setItem('mathquiz_users', JSON.stringify(users));
  return users;
}

// LƯU CẢ VÀO LOCALSTORAGE VÀ ĐỒNG BỘ TRỰC TIẾP LÊN SERVER
function saveUsersDB(users) {
  localStorage.setItem('mathquiz_users', JSON.stringify(users));
  // Tự động lưu ra server file users_db.json
  try {
    fetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(users)
    }).catch(() => {});
  } catch (e) {}
}

// TỰ ĐỘNG ĐỒNG BỘ TÀI KHOẢN TỪ SERVER VỀ MÁY HỌC SINH
async function syncUsersFromServer() {
  try {
    const res = await fetch('/api/users');
    if (res.ok) {
      const serverUsers = await res.json();
      if (Array.isArray(serverUsers) && serverUsers.length > 0) {
        let current = getUsersDB();
        serverUsers.forEach(su => {
          const idx = current.findIndex(u => u.username.toLowerCase() === su.username.toLowerCase());
          if (idx >= 0) {
            current[idx] = su;
          } else {
            current.push(su);
          }
        });
        localStorage.setItem('mathquiz_users', JSON.stringify(current));
        if (state.screen === 'admin') render();
      }
    }
  } catch (err) {}
}

