const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const root = 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes';
const popplerBin = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\poppler\\poppler-24.08.0\\Library\\bin';
const pdfinfo = path.join(popplerBin, 'pdfinfo.exe');
const pdftoppm = path.join(popplerBin, 'pdftoppm.exe');
const tempDir = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\archimedes_samples';

if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

function walk(dir) {
  let results = [];
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    const full = path.join(dir, file);
    const stat = fs.statSync(full);
    if (stat && stat.isDirectory()) {
      results = results.concat(walk(full));
    } else if (file.toLowerCase().endsWith('.pdf')) {
      results.push({ name: file, full, size: (stat.size / 1024 / 1024).toFixed(1) + 'MB' });
    }
  });
  return results;
}

const files = walk(root);
console.log(`Found ${files.length} PDF files:`);

const summary = [];
files.forEach((f, idx) => {
  // copy to temp ascii to run pdfinfo
  const tempPdf = path.join(tempDir, `sample_${idx}.pdf`);
  fs.copyFileSync(f.full, tempPdf);
  try {
    const out = execSync(`"${pdfinfo}" "${tempPdf}"`).toString();
    const m = out.match(/Pages:\s+(\d+)/);
    const pages = m ? parseInt(m[1]) : 0;
    const item = {
      index: idx,
      path: f.full,
      name: f.name,
      size: f.size,
      pages
    };
    summary.push(item);
    console.log(`[${idx + 1}/${files.length}] ${f.name} - ${f.size} - ${pages} pages`);
  } catch (e) {
    console.error(`Error with ${f.name}:`, e.message);
  } finally {
    if (fs.existsSync(tempPdf)) fs.unlinkSync(tempPdf);
  }
});

fs.writeFileSync(path.join(tempDir, 'summary.json'), JSON.stringify(summary, null, 2), 'utf8');
console.log('Saved summary.json');

