      --accent: #F59E0B;
      --accent-gradient: linear-gradient(135deg, #F59E0B 0%, #D97706 100%);
      --success: #10B981;
      --success-gradient: linear-gradient(135deg, #10B981 0%, #059669 100%);
      --danger: #EF4444;
      --bg-glass: rgba(255, 255, 255, 0.94);
      --card-border: rgba(226, 232, 240, 0.85);
      --text: #0F172A;
      --text-muted: #64748B;
      --border: #E2E8F0;
      --shadow-sm: 0 2px 4px rgba(15, 23, 42, 0.04);
      --shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.08), 0 8px 10px -6px rgba(15, 23, 42, 0.04);
      --shadow-lg: 0 20px 35px -5px rgba(37, 99, 235, 0.15), 0 10px 15px -5px rgba(0, 0, 0, 0.04);
      --radius: 20px;
      --radius-sm: 14px;
      --radius-full: 9999px;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      -webkit-tap-highlight-color: transparent;
    }

    body {
      font-family: 'Times New Roman', Times, serif;
      background: #EDF2F7;
      background-image: url('banner_fixed_full.jpg');
      background-size: cover;
      background-position: center top;
      background-attachment: fixed;
      color: var(--text);
      line-height: 1.65;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      font-size: 1.05em;
      position: relative;
    }

    /* LỚP PHỦ LÀM NÉT VÀ MỀM HÓA ẢNH NỀN THEO CHUẨN DESIGN SYSTEM */
    body::before {
      content: '';
      position: fixed;
      top: 0; left: 0; right: 0; bottom: 0;
      background: linear-gradient(135deg, rgba(241, 245, 249, 0.88) 0%, rgba(224, 231, 255, 0.92) 100%);
      backdrop-filter: blur(5px);
      -webkit-backdrop-filter: blur(5px);
      z-index: -1;
    }

    #app {
      max-width: 900px;
      width: 100%;
      margin: 0 auto;
      padding: 20px 16px;
      flex: 1;
    }

    /* ===== BANNER TÁC GIẢ ===== */
    .top-banner {
      background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
