const fs = require('fs');
const { execSync } = require('child_process');
const pdftotext = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\poppler\\poppler-24.08.0\\Library\\bin\\pdftotext.exe';

const files = [
  { grade: 1, path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 1\\toán q1.pdf' },
  { grade: 2, path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 2\\Toán lớp 2 quyển 1.pdf' },
  { grade: 3, path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 3\\Toan 3- Q1.pdf' },
  { grade: 4, path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 4\\toasn 4 q1.pdf' },
  { grade: 5, path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 5\\toán lớp 5 q1.pdf' },
  { grade: 1, sub: 'tv', path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 1\\tiếng việt q1.pdf' },
  { grade: 4, sub: 'tv', path: 'V:\\ChinhND\\Đề ôn tập\\Bộ bài tập Archimedes\\Lớp 4\\tiếng việt 4 quyển 1.pdf' }
];

files.forEach(f => {
  const tempPdf = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\temp_ext.pdf';
  const outTxt = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\temp_ext.txt';
  try {
    fs.copyFileSync(f.path, tempPdf);
    execSync(`"${pdftotext}" -f 1 -l 15 "${tempPdf}" "${outTxt}"`);
    const txt = fs.readFileSync(outTxt, 'utf8');
    console.log(`[Grade ${f.grade} ${f.sub || 'math'}] Text length: ${txt.trim().length}`);
    if (txt.trim().length > 0) {
      console.log(`Preview: ${txt.substring(0, 200).replace(/\r?\n/g, ' ')}`);
    }
  } catch(e) {
    console.error(`Error Grade ${f.grade}:`, e.message);
  } finally {
    if (fs.existsSync(tempPdf)) fs.unlinkSync(tempPdf);
    if (fs.existsSync(outTxt)) fs.unlinkSync(outTxt);
  }
});

