const fs = require('fs');
const path = require('path');

const dir = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\toan-quoc-te';

function cleanText(text) {
  if (!text) return text;
  return text
    // Dấu phép tính toán học
    .replace(/[\uF0B8]/g, '÷')
    .replace(/[\uF0B4\uF0CD]/g, '×')
    .replace(/[\u2212−]/g, '-')
    .replace(/[\uF0B9]/g, '≠')
    .replace(/[\uF03C]/g, '<')
    .replace(/[\uF0C4\uF02A\uF077\uF0A7\uF051]/g, '⨂')
    .replace(/[\uF0C5]/g, '⨁')
    // Mũi tên suy ra
    .replace(/[\uF0F0\uF0F1\uF067\uF0DC]/g, '➜')
    // Hình học
    .replace(/[\uF044]/g, '△')
    .replace(/[\uF071\uF072\uF0D9]/g, '▲')
    .replace(/[\uF076]/g, '▼')
    .replace(/[\uF0D8]/g, '▶')
    .replace(/[\uF098\uF070\uF073]/g, '●')
    .replace(/[\uF099\uF0A1]/g, '○')
    .replace(/[\uF0A3]/g, '□')
    .replace(/[\uF0A2]/g, '■')
    .replace(/[\uF0EA\uF0AB]/g, '★')
    .replace(/[\uF0A8]/g, '◇')
    .replace(/[\uF0A9]/g, '❤')
    // Ký hiệu chuỗi số bí ẩn
    .replace(/[\uF0AF\uF0B6\uF050]/g, '?')
    .replace(/[\uF026]/g, '📖')
    .replace(/[\uF0BE]/g, '—')
    .replace(/[\uF0BC]/g, '...')
    .replace(/[\uF096]/g, '•')
    .replace(/[\uF0E6\uF0E7\uF0E8]/g, '(')
    .replace(/[\uF0F7\uF0F8]/g, ')');
}

const targetFiles = [
  'timo_data.js',
  'grade4_special.js',
  'extra_exams.js',
  'archimedes_math_data.js',
  'tieng_viet_data.js'
];

targetFiles.forEach(file => {
  const filePath = path.join(dir, file);
  if (fs.existsSync(filePath)) {
    console.log(`Processing ${file}...`);
    let content = fs.readFileSync(filePath, 'utf8');
    let cleaned = cleanText(content);
    if (content !== cleaned) {
      fs.writeFileSync(filePath, cleaned, 'utf8');
      console.log(`✅ Updated ${file}`);
    } else {
      console.log(`- No changes needed for ${file}`);
    }
  }
});

console.log('Done cleaning database files.');

