const fs = require('fs');
const path = require('path');

const dataFile = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\toan-quoc-te\\timo_data.js';
let content = fs.readFileSync(dataFile, 'utf8');

// Định nghĩa dữ liệu chuẩn 100% trích xuất từ sách TIMO 4.pdf chính thức của FERMAT
const corrections = {
  // 1. Câu 63 x 9 - 63 + 42 x 9 + 84 x 2 (Vòng quốc gia Đề 1, Câu 6)
  "4-Vong quoc gia - De so 0-6": {
    round: "Vòng quốc gia - Đề số 1",
    num: 6,
    answer: "1050",
    explanation: "63 × 9 - 63 + 42 × 9 + 84 × 2\n= 21 × 3 × 9 - 21 × 3 + 21 × 2 × 9 + 21 × 4 × 2\n= 21 × 27 - 21 × 3 + 21 × 18 + 21 × 8\n= 21 × (27 - 3 + 18 + 8)\n= 21 × 50\n= 1050.\nĐáp số: 1050."
  },

  // 2. Câu 54 : 16 x 100 : 9 x 40 (Vòng quốc gia Đề 1, Câu 8)
  "4-Vong quoc gia - De so 0-8": {
    // Note: Có 2 câu có id kết thúc bằng -8 trong đề 0, phân biệt theo text
    filter: (q) => q.text.includes('54 : 16'),
    round: "Vòng quốc gia - Đề số 1",
    num: 8,
    answer: "1500",
    explanation: "54 : 16 × 100 : 9 × 40\n= (54 × 100 × 40) : (16 × 9)\n= 216000 : 144\n= 1500.\nĐáp số: 1500."
  },

  // 3. Câu 36 ÷ 21 x 106 ÷ 8 x 14 (Vòng quốc gia Đề 4, Câu 8)
  "4-Vong quoc gia - De so 0-8-36": {
    filter: (q) => q.text.includes('36 ÷ 21') || q.text.includes('36 : 21'),
    round: "Vòng quốc gia - Đề số 4",
    num: 8,
    answer: "318",
    explanation: "36 : 21 × 106 : 8 × 14\n= (36 : 21 × 14) × (106 : 8)\n= (12/7 × 14) × 106 : 8\n= 24 : 8 × 106\n= 3 × 106\n= 318.\nĐáp số: 318."
  },

  // 4. Câu 7 + 10 + 13 + ... + 73 (Vòng quốc gia Đề 1, Câu 9)
  "4-Vong quoc gia - De so 0-9": {
    filter: (q) => q.text.includes('7 + 10 + 13'),
    round: "Vòng quốc gia - Đề số 1",
    num: 9,
    answer: "920",
    explanation: "Dãy số cách đều 3 đơn vị: 7, 10, 13, ..., 73.\nSố số hạng = (73 - 7) : 3 + 1 = 23 (số).\nTổng S = (7 + 73) × 23 : 2 = 80 × 23 : 2 = 920.\nĐáp số: 920."
  },

  // 5. Câu 13 : 6 - 38 : 6 + 59 : 6 - 7 : 6 + 45 : 6 (Vòng quốc gia Đề 4, Câu 9)
  "4-Vong quoc gia - De so 0-9-13": {
    filter: (q) => q.text.includes('13 ÷ 6') || q.text.includes('13 : 6'),
    round: "Vòng quốc gia - Đề số 4",
    num: 9,
    answer: "12",
    explanation: "13 : 6 - 38 : 6 + 59 : 6 - 7 : 6 + 45 : 6\n= (13 - 38 + 59 - 7 + 45) : 6\n= (13 + 59 + 45 - 38 - 7) : 6\n= (117 - 45) : 6\n= 72 : 6 = 12.\nĐáp số: 12."
  },

  // 6. Câu 1 - 9 + 15 - 21 + ... + 75 (Vòng quốc gia Đề 1, Câu 10)
  "4-Vong quoc gia - De so 0-10": {
    filter: (q) => q.text.includes('1 - 9 + 15'),
    round: "Vòng quốc gia - Đề số 1",
    num: 10,
    answer: "37",
    explanation: "1 - 9 + 15 - 21 + 27 - 33 + 39 - 45 + 51 - 57 + 63 - 69 + 75\n= 1 + (-9 + 15) + (-21 + 27) + (-33 + 39) + (-45 + 51) + (-57 + 63) + (-69 + 75)\n= 1 + 6 + 6 + 6 + 6 + 6 + 6\n= 1 + 6 × 6 = 37.\nĐáp số: 37."
  },

  // 7. Câu 24 x 28 - 80 + 2 x 36 (Vòng quốc gia Đề 4, Câu 10)
  "4-Vong quoc gia - De so 0-10-24": {
    filter: (q) => q.text.includes('24 × 28') || q.text.includes('24 x 28'),
    round: "Vòng quốc gia - Đề số 4",
    num: 10,
    answer: "664",
    explanation: "24 × 28 - 80 + 2 × 36\n= 672 - 80 + 72\n= 592 + 72\n= 664.\nĐáp số: 664."
  },

  // 8. Câu đếm hình lập phương thứ 10 (Vòng quốc gia Đề 5, Câu 19)
  "4-Vong quoc gia - De so 0-19": {
    filter: (q) => q.text.includes('cubes are there in 10th group'),
    round: "Vòng quốc gia - Đề số 5",
    num: 19,
    image: "images/timo_g4_q19_cubes.png",
    answer: "29",
    explanation: "Quy luật số hình lập phương theo từng nhóm:\n- Nhóm 1: 2 hình\n- Nhóm 2: 5 hình\n- Nhóm 3: 8 hình\nQuy luật: Mỗi nhóm tăng thêm 3 hình lập phương so với nhóm liền trước.\nSố hình lập phương ở nhóm thứ n là: 2 + 3 × (n - 1) = 3n - 1.\nỞ hình thứ 10 (10th group), số hình lập phương là: 3 × 10 - 1 = 29 hình.\nĐáp số: 29."
  },

  // 9. Câu cắt sợi ruy băng 27 giây (Vòng quốc gia Đề 4, Câu 1)
  "4-Vong quoc gia - De so 0-1-ribbon": {
    filter: (q) => q.text.includes('27 seconds to cut a ribbon'),
    round: "Vòng quốc gia - Đề số 4",
    num: 1,
    answer: "12",
    explanation: "Để cắt sợi ruy băng thành 10 phần cần 9 nhát cắt.\nThời gian thực hiện 1 nhát cắt là: 27 : 9 = 3 (giây).\nĐể cắt sợi ruy băng thành 5 phần cần 4 nhát cắt.\nThời gian cần dùng là: 3 × 4 = 12 (giây).\nĐáp số: 12."
  },

  // 10. Câu cắt khúc gỗ 63 phút (Vòng quốc gia Đề 3, Câu 1)
  "4-Vong quoc gia - De so 0-1-wood": {
    filter: (q) => q.text.includes('63 minutes to cut a piece of wood'),
    round: "Vòng quốc gia - Đề số 3",
    num: 1,
    answer: "98",
    explanation: "Cắt khúc gỗ thành 10 đoạn cần 9 lần cưa.\nThời gian cưa 1 lần là: 63 : 9 = 7 (phút).\nĐể cắt thành 15 đoạn cần 14 lần cưa.\nThời gian cần dùng là: 7 × 14 = 98 (phút).\nĐáp số: 98."
  },

  // 11. Câu tìm chu vi chữ nhật diện tích 60 (Vòng quốc gia Đề 3, Câu 18)
  "4-Vong quoc gia - De so 0-18-area60": {
    filter: (q) => q.text.includes('area of a rectangle is 60'),
    round: "Vòng quốc gia - Đề số 3",
    num: 18,
    answer: "32",
    explanation: "Các cặp chiều dài, chiều rộng có tích bằng 60:\n(60, 1), (30, 2), (20, 3), (15, 4), (12, 5), (10, 6).\nĐể chu vi nhỏ nhất thì chiều dài và chiều rộng gần nhau nhất: (10, 6).\nChu vi nhỏ nhất = (10 + 6) × 2 = 32 cm.\nĐáp số: 32."
  },

  // 12. Câu chu vi chữ nhật 60cm tìm diện tích lớn nhất (Vòng quốc gia Đề 1, Câu 18)
  "4-Vong quoc gia - De so 0-18-perim60": {
    filter: (q) => q.text.includes('perimeter of a rectangle is 60'),
    round: "Vòng quốc gia - Đề số 1",
    num: 18,
    answer: "225",
    explanation: "Nửa chu vi hình chữ nhật = 60 : 2 = 30 cm.\nĐể diện tích lớn nhất, chiều dài và chiều rộng gần nhau nhất: 15 cm và 15 cm.\nDiện tích lớn nhất = 15 × 15 = 225 cm².\nĐáp số: 225."
  },

  // 13. Câu 25 hình vuông nhỏ ghép thành hình lớn (Vòng quốc gia Đề 3, Câu 16)
