h = h.replace("selectAnswer(${q.id}, this.value.trim())", "selectAnswer('${q.id}', this.value.trim())");

// 2. Add isAnswerCorrect and upgrade submitQuiz
const oldSubmit = `    function submitQuiz() {
      clearInterval(state.timerInterval);

      let correct = 0, wrong = 0, skipped = 0;
      const details = state.questions.map(q => {
        const userAns = (state.answers[q.id] || '').toString().trim().toUpperCase();
        const correctAns = (q.answer || '').toString().trim().toUpperCase();
        let status = 'skipped';
        if (!userAns) skipped++;
        else if (userAns === correctAns) {
          status = 'correct';
          correct++;
        } else {
          status = 'wrong';
          wrong++;
        }
        return { ...q, userAns, correctAns, status };
      });`;

const newSubmit = `    // HÀM SO KHỚP ĐÁP ÁN THÔNG MINH CHO CẢ TRẮC NGHIỆM VÀ TỰ ĐIỀN ĐÁP SỐ
    function isAnswerCorrect(userAns, q) {
      if (userAns === undefined || userAns === null || userAns === '') return false;
      const u = userAns.toString().trim();
      const c = (q.answer || '').toString().trim();
      if (!u || !c) return false;

      // So khớp nguyên bản (không phân biệt hoa thường)
      if (u.toUpperCase() === c.toUpperCase()) return true;

      // Làm sạch khoảng trắng và dấu chấm câu
      const cleanU = u.toLowerCase().replace(/\\s+/g, '').replace(/,/g, ';').replace(/\\.$/, '');
      const cleanC = c.toLowerCase().replace(/\\s+/g, '').replace(/,/g, ';').replace(/\\.$/, '');
      if (cleanU === cleanC) return true;

      // Bỏ tiền tố biến số nếu bé nhập: "y = 51" -> "51", "a = 398" -> "398"
      const stripPreU = cleanU.replace(/^[yabx]=/, '');
      const stripPreC = cleanC.replace(/^[yabx]=/, '');
      if (stripPreU === stripPreC) return true;

      // Bỏ đuôi đơn vị thông dụng nếu bé gõ kèm đơn vị
      const stripUnits = str => str.replace(/(tuổi|tấn|tạ|yến|kg|g|m|cm|dm|km|cm2|cm²|m2|m²|lần|số|giây|phút|giờ|năm|chiếc)$/i, '').trim();
      if (stripUnits(cleanU) === stripUnits(cleanC)) return true;

      // Kiểm tra danh sách đáp án tương đương (acceptedAnswers)
      if (Array.isArray(q.acceptedAnswers)) {
        for (const alt of q.acceptedAnswers) {
          const aStr = alt.toString().trim();
          if (u.toUpperCase() === aStr.toUpperCase()) return true;
          const aClean = aStr.toLowerCase().replace(/\\s+/g, '').replace(/,/g, ';').replace(/\\.$/, '');
          if (cleanU === aClean || stripPreU === aClean || stripUnits(cleanU) === stripUnits(aClean)) return true;
        }
      }

      // So sánh số thuần túy (ví dụ "12238406" so với "12 238 406")
      if (!u.includes(';') && !c.includes(';') && !u.includes('>') && !c.includes('>') && !u.includes('<') && !c.includes('<') && !u.includes('=')) {
        const numU = u.replace(/[^0-9]/g, '');
        const numC = c.replace(/[^0-9]/g, '');
        if (numU && numC && numU === numC) return true;
      }

      return false;
    }

    function submitQuiz() {
      clearInterval(state.timerInterval);

      let correct = 0, wrong = 0, skipped = 0;
      const details = state.questions.map(q => {
        const userAns = (state.answers[q.id] !== undefined ? state.answers[q.id] : '').toString().trim();
        const correctAns = (q.answer || '').toString().trim();
        let status = 'skipped';
        if (!userAns) skipped++;
        else if (isAnswerCorrect(userAns, q)) {
          status = 'correct';
          correct++;
        } else {
          status = 'wrong';
          wrong++;
        }
        return { ...q, userAns, correctAns, status };
      });`;

