  const p = path.join(dir, '05_BÀI TOÁN GÀ VÀ THỎ_LỜI GIẢI.pdf');
  const text = cp.execSync(`"C:/Users/HNBV3384/.gemini/antigravity/scratch/tools/poppler/poppler-24.08.0/Library/bin/pdftotext.exe" "${p}" -`, { encoding: 'utf8' });
  const rawBlocks = text.split(/\n(?=\d+\.\s+\[ĐVH\])/);
