    const m = block.match(/^(\d+)\.\s+\[ĐVH\]([\s\S]*)/);
    if (!m) return;
    const num = parseInt(m[1], 10);
    const content = m[2].trim();
    // Split into question and solution
    // Solution usually starts with  or Lời giải: or Giả sử
    let qText = content;
    let exp = '';
    let ans = '';
    const solIdx = content.search(/(|Lời giải:|Hướng dẫn giải:)/);
    if (solIdx !== -1) {
      qText = content.substring(0, solIdx).trim();
      exp = content.substring(solIdx).trim();
      // Extract answer from last line of exp
      const lastLine = exp.split('\n').filter(Boolean).pop() || '';
      const ansMatch = lastLine.match(/(Vậy\s+có|Đáp số:|Đáp án:)\s*(.*)/i);
      if (ansMatch) ans = ansMatch[2].trim().replace(/\.$/, '');
    }
    items.push({ num, qText, exp, ans });
  });
  return items;
}

