const fs = require('fs');
const path = 'V:\\ChinhND\\Đề ôn tập\\365 Bài toán hay và khó lớp 4';

const files = fs.readdirSync(path).filter(f => f.endsWith('.html'));

function parseFile(fileName) {
  const content = fs.readFileSync(`${path}\\${fileName}`, 'utf8');

  // Split into problem section and solution section
  const solSectionStart = content.indexOf('HƯỚNG DẪN GIẢI VÀ ĐÁP ÁN CHI TIẾT');
  if (solSectionStart === -1) {
    console.error(`No solution section in ${fileName}`);
    return;
  }

  const probContent = content.substring(0, solSectionStart);
  const solContent = content.substring(solSectionStart);

  // Extract solutions: <div class="sol-item"><span class="sol-num">Bài X:</span> ... <strong>ANSWER</strong> ... </div>
  const solMap = {};
  const solRegex = /<div class="sol-item"><span class="sol-num">Bài\s*(\d+):<\/span>([\s\S]*?)<\/div>/g;
  let sm;
  while ((sm = solRegex.exec(solContent)) !== null) {
    const num = parseInt(sm[1], 10);
    const body = sm[2].trim();
    // Extract strong tags for answer
    const strongMatch = body.match(/<strong>(.*?)<\/strong>/g);
    let extractedAns = '';
    if (strongMatch) {
      extractedAns = strongMatch.map(s => s.replace(/<\/?strong>/g, '').trim()).join('; ');
    }
    solMap[num] = {
      raw: body,
      ans: extractedAns,
      cleanText: body.replace(/<[^>]+>/g, '').trim()
    };
  }

  // Extract chapters and problems
  // Chapters: <div class="chapter-header">CHỦ ĐỀ X: ...</div>
  const chapterSplits = probContent.split(/<div class="chapter-header">/);
  console.log(`\n=== ${fileName} ===`);
  console.log(`Found ${Object.keys(solMap).length} solutions.`);

  let fileProbCount = 0;
  for (let c = 1; c < chapterSplits.length; c++) {
    const part = chapterSplits[c];
    const chapTitle = part.substring(0, part.indexOf('</div>')).trim();
    const probRegex = /<div class="problem-item"><span class="problem-num">Bài\s*(\d+):<\/span>([\s\S]*?)<\/div>/g;
    let pm;
    const chapProblems = [];
    while ((pm = probRegex.exec(part)) !== null) {
      const num = parseInt(pm[1], 10);
      const text = pm[2].replace(/<[^>]+>/g, '').trim();
      const sol = solMap[num];
      chapProblems.push({ num, text, ans: sol ? sol.ans : 'N/A' });
      fileProbCount++;
    }
    console.log(`Chương: "${chapTitle}" -> ${chapProblems.length} bài. [Bài ${chapProblems[0]?.num} - ${chapProblems[chapProblems.length-1]?.num}]`);
    if (chapProblems.length > 0) {
      console.log(`   Ví dụ bài ${chapProblems[0].num}: ${chapProblems[0].text.substring(0, 60)}... -> Ans: "${chapProblems[0].ans}"`);
    }
  }
  console.log(`Total problems in ${fileName}: ${fileProbCount}`);
}

