const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const xmlPath = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc4_de1.xml';
const xmlContent = fs.readFileSync(xmlPath, 'utf8');

// Parse image tags by page
const pages = xmlContent.split('</page>');
const diagramsByPage = {};

pages.forEach((pageContent, idx) => {
  const pageNum = idx + 1;
  const imgRegex = /<image top="(\d+)" left="(\d+)" width="(\d+)" height="(\d+)" src="([^"]+)"\/>/g;
  let m;
  const list = [];
  while ((m = imgRegex.exec(pageContent)) !== null) {
    const top = parseInt(m[1], 10);
    const left = parseInt(m[2], 10);
    const width = parseInt(m[3], 10);
    const height = parseInt(m[4], 10);
    const src = m[5];
    // filter out logo and radio icons
    if (width === 112 || width === 30) continue;
    list.push({ top, left, width, height, right: left + width, bottom: top + height, src });
  }
  if (list.length > 0) {
    diagramsByPage[pageNum] = list;
  }
});

console.log('Diagrams by page:', JSON.stringify(diagramsByPage, null, 2));

