const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const xmlContent = fs.readFileSync('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc3_full.xml', 'utf8');
const textContent = fs.readFileSync('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc3_full.txt', 'utf8');

// Parse pages
const pageRegex = /<page\s+number="(\d+)"[^>]*>([\s\S]*?)<\/page>/g;
let m;
const pageMap = {};

while ((m = pageRegex.exec(xmlContent)) !== null) {
  const pNum = parseInt(m[1], 10);
  const content = m[2];

  const textRegex = /<text\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"[^>]*>(?:<[^>]+>)*([^<]*)(?:<\/[^>]+>)*<\/text>/g;
  let tm;
  const texts = [];
  while ((tm = textRegex.exec(content)) !== null) {
    const val = tm[5].trim();
    if (val) {
      texts.push({
        top: parseInt(tm[1], 10),
        left: parseInt(tm[2], 10),
        width: parseInt(tm[3], 10),
        height: parseInt(tm[4], 10),
        text: val
      });
    }
  }

  const imgRegex = /<image\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"\s+src="([^"]+)"\/>/g;
  let im;
  const images = [];
  while ((im = imgRegex.exec(content)) !== null) {
    const w = parseInt(im[3], 10);
    const h = parseInt(im[4], 10);
    if (w === 112 || w === 30) continue;
    images.push({
      top: parseInt(im[1], 10),
      left: parseInt(im[2], 10),
      width: w,
      height: h,
      right: parseInt(im[2], 10) + w,
      bottom: parseInt(im[1], 10) + h,
      src: im[5]
    });
  }

  pageMap[pNum] = { texts, images };
}

// Find test titles in Grade 3
const testTitles = [];
for (let p in pageMap) {
  const pData = pageMap[p];
  const full = pData.texts.map(t => t.text).join(' ');
  const tm = full.match(/Toán\s+Kangaroo\s+Lớp\s+3\s*–\s*Số\s+(\d+)/i);
  if (tm) {
    testTitles.push({ deNum: parseInt(tm[1], 10), page: parseInt(p, 10) });
  }
}
testTitles.sort((a, b) => a.page - b.page);
console.log('Grade 3 tests found:', testTitles);

// Build page ranges for each test
const dePages = [];
for (let i = 0; i < testTitles.length; i++) {
  const start = testTitles[i].page;
  const end = (i + 1 < testTitles.length) ? testTitles[i + 1].page - 1 : 63;
  dePages.push({ de: testTitles[i].deNum, start, end });
}

// Group images to questions
const allCrops = [];
dePages.forEach(dp => {
  let activeQ = 1;
  for (let p = dp.start; p <= dp.end; p++) {
    const pData = pageMap[p];
    if (!pData) continue;

    const qOnPage = [];
    pData.texts.forEach(t => {
      if (t.text.includes('Toán Kangaroo') || t.text.includes('kynaforkids')) return;
      const match = t.text.match(/^(\d+)\.\s*(.*)/);
      if (match && parseInt(match[1], 10) <= 30) {
        qOnPage.push({
          qNum: parseInt(match[1], 10),
          top: t.top,
          text: match[2]
        });
      }
    });

    pData.images.forEach(img => {
      let qNum = activeQ;
      for (let i = qOnPage.length - 1; i >= 0; i--) {
        if (qOnPage[i].top <= img.top + 30) {
          qNum = qOnPage[i].qNum;
          break;
        }
      }
      allCrops.push({
        de: dp.de,
        qNum: qNum || 1,
        page: p,
        top: img.top,
        bottom: img.bottom,
        left: img.left,
        right: img.right
      });
    });

    if (qOnPage.length > 0) {
      activeQ = qOnPage[qOnPage.length - 1].qNum;
    }
  }
});

const mergedCrops = {};
allCrops.forEach(c => {
  const key = `g3_de${c.de}_q${c.qNum.toString().padStart(2, '0')}`;
  if (!mergedCrops[key]) {
    mergedCrops[key] = {
      key,
      de: c.de,
      qNum: c.qNum,
      page: c.page,
      minTop: c.top,
      maxBottom: c.bottom,
      minLeft: c.left,
      maxRight: c.right
    };
  } else if (mergedCrops[key].page === c.page) {
    mergedCrops[key].minTop = Math.min(mergedCrops[key].minTop, c.top);
    mergedCrops[key].maxBottom = Math.max(mergedCrops[key].maxBottom, c.bottom);
    mergedCrops[key].minLeft = Math.min(mergedCrops[key].minLeft, c.left);
    mergedCrops[key].maxRight = Math.max(mergedCrops[key].maxRight, c.right);
  }
});

const cropList = Object.values(mergedCrops);
console.log(`Grade 3: total diagrams to crop: ${cropList.length}`);
fs.writeFileSync('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc3_crop_list.json', JSON.stringify(cropList, null, 2));

