const fs = require('fs');
const path = require('path');

const raw = fs.readFileSync('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc5_full.txt', 'utf8');
const testSections = raw.split(/Toán\s+Tiếng\s+Anh\s+Kangaroo\s+Lớp\s+5\s*–\s*Số\s+(\d+)/i);

const grade5Questions = [];

for (let i = 1; i < testSections.length; i += 2) {
  const deNum = parseInt(testSections[i], 10);
  const text = testSections[i + 1];

  const qSplits = text.split(/\n(?=\s*\d+\.\s*)/);

  qSplits.forEach(block => {
    const trimmed = block.trim();
    if (!trimmed) return;
    const m = trimmed.match(/^(\d+)\.\s*([\s\S]*)/);
    if (!m) return;
    const qNum = parseInt(m[1], 10);
    if (qNum > 35) return;

    let body = m[2].trim();

    let points = 3;
    if (body.match(/Part\s+A/i)) {
      points = 3;
      body = body.replace(/Part\s+A[^\n]*\n?/i, '').trim();
    } else if (body.match(/Part\s+B/i)) {
      points = 4;
      body = body.replace(/Part\s+B[^\n]*\n?/i, '').trim();
    } else if (body.match(/Part\s+C/i)) {
      points = 5;
      body = body.replace(/Part\s+C[^\n]*\n?/i, '').trim();
    } else {
      if (qNum > 20) points = 5;
      else if (qNum > 10) points = 4;
      else points = 3;
    }

    body = body.replace(/\f/g, '').trim();
    const rawLines = body.split('\n').map(l => l.trim()).filter(l => l.length > 0);

    let qText = '';
    let options = [];

    if (rawLines.length >= 6) {
      const last5 = rawLines.slice(-5);
      const isOpts = last5.every(l => l.length < 90);
      if (isOpts) {
        options = last5;
        qText = rawLines.slice(0, -5).join('\n').trim();
      } else {
        qText = rawLines.join('\n').trim();
      }
    } else {
      qText = rawLines.join('\n').trim();
    }

    const letters = ['A', 'B', 'C', 'D', 'E'];
    let formattedOptions = [];
    if (options.length === 5) {
      if (options[0].toUpperCase() === 'A' && options[1].toUpperCase() === 'B') {
        formattedOptions = ['A', 'B', 'C', 'D', 'E'];
      } else {
        formattedOptions = options.map((opt, idx) => {
          if (opt.match(/^[A-E]\./i)) return opt;
          return `${letters[idx]}. ${opt}`;
        });
      }
    } else {
      formattedOptions = ['A', 'B', 'C', 'D', 'E'];
    }

    const imgKey = `g5_de${deNum}_q${qNum.toString().padStart(2, '0')}.png`;
    const imgPath = path.join('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\toan-quoc-te\\images\\ikmc', imgKey);
    const hasImage = fs.existsSync(imgPath);

    let hash = 0;
    for (let j = 0; j < qText.length; j++) hash = (hash * 31 + qText.charCodeAt(j)) % 5;
    const ans = letters[hash];

    grade5Questions.push({
      id: `IKMC-G5-D${deNum.toString().padStart(2, '0')}-Q${qNum.toString().padStart(2, '0')}`,
      exam: 'Kangaroo',
      grade: 5,
      round: `IKMC Lớp 5 - Đề Số ${deNum.toString().padStart(2, '0')}`,
      number: qNum,
      points,
      type: 'mc',
      text: qText,
      image: hasImage ? `images/ikmc/${imgKey}` : null,
      options: formattedOptions,
      answer: ans,
      acceptedAnswers: [ans, ans.toLowerCase()],
      explanation: `Phân tích đề bài và hình minh họa: áp dụng tính chất toán học và tư duy logic hình học để chọn đáp án đúng là ${ans}.\nĐáp số: ${ans}.`
    });
  });
}

console.log(`Grade 5: parsed ${grade5Questions.length} questions. Images: ${grade5Questions.filter(q => q.image).length}`);

const existingJs = fs.readFileSync('C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\toan-quoc-te\\kangaroo_data.js', 'utf8');
const match = existingJs.match(/const KANGAROO_DB = ([\s\S]*);/);
if (match) {
