function getCrops(gNum, xmlPath, pageDir, ranges) {
  const xmlContent = fs.readFileSync(xmlPath, 'utf8');
  const pageRegex = /<page\s+number="(\d+)"[^>]*>([\s\S]*?)<\/page>/g;
  let m;
  const pageMap = {};

  while ((m = pageRegex.exec(xmlContent)) !== null) {
    const pNum = parseInt(m[1], 10);
    const content = m[2];

    const textRegex = /<text\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"[^>]*>(?:<[^>]+>)*([^<]*)(?:<\/[^>]+>)*<\/text>/g;
    let tm;
    const texts = [];
    while ((tm = textRegex.exec(content)) !== null) {
      const val = tm[5].trim();
      if (val) {
        texts.push({
          top: parseInt(tm[1], 10),
          left: parseInt(tm[2], 10),
          width: parseInt(tm[3], 10),
          height: parseInt(tm[4], 10),
          text: val
        });
      }
    }

    const imgRegex = /<image\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"\s+src="([^"]+)"\/>/g;
    let im;
    const images = [];
    while ((im = imgRegex.exec(content)) !== null) {
      const w = parseInt(im[3], 10);
      const h = parseInt(im[4], 10);
      if (w === 133 || w === 112 || w === 30) continue;
      images.push({
        top: parseInt(im[1], 10),
        left: parseInt(im[2], 10),
        width: w,
        height: h,
        right: parseInt(im[2], 10) + w,
        bottom: parseInt(im[1], 10) + h,
        src: im[5]
      });
    }

    pageMap[pNum] = { texts, images };
  }

  const allCrops = [];
  ranges.forEach(dp => {
