            text: match[2]
          });
        }
      });

      pData.images.forEach(img => {
        let qNum = activeQ;
        for (let i = qOnPage.length - 1; i >= 0; i--) {
          if (qOnPage[i].top <= img.top + 30) {
            qNum = qOnPage[i].qNum;
            break;
          }
        }
        allCrops.push({
          de: dp.de,
          qNum: qNum || 1,
          page: p,
          top: img.top,
          bottom: img.bottom,
          left: img.left,
          right: img.right
        });
      });

      if (qOnPage.length > 0) {
        activeQ = qOnPage[qOnPage.length - 1].qNum;
      }
    }
  });

  const mergedCrops = {};
  allCrops.forEach(c => {
    const key = `g${gNum}_de${c.de}_q${c.qNum.toString().padStart(2, '0')}`;
    if (!mergedCrops[key]) {
      mergedCrops[key] = {
        key,
        gNum,
        de: c.de,
        qNum: c.qNum,
        page: c.page,
        minTop: c.top,
        maxBottom: c.bottom,
        minLeft: c.left,
