async function handleLogin() {
  const rawU = document.getElementById('loginUser').value.trim();
  const p = document.getElementById('loginPass').value.trim();
  const cleanU = rawU.replace(/^@+/, '').trim().toLowerCase();
  let users = getUsersDB();
  let found = users.find(x => (x.username || '').replace(/^@+/, '').trim().toLowerCase() === cleanU && (x.pass || '').trim() === p);

  // Nếu chưa tìm thấy, thử đồng bộ ngay từ máy chủ về (hỗ trợ khi tài khoản vừa được tạo trên thiết bị khác)
  if (!found) {
    try {
      const res = await fetch('/api/users');
      if (res.ok) {
        const serverUsers = await res.json();
        if (Array.isArray(serverUsers) && serverUsers.length > 0) {
          localStorage.setItem('mathquiz_users', JSON.stringify(serverUsers));
          users = getUsersDB();
          found = users.find(x => (x.username || '').replace(/^@+/, '').trim().toLowerCase() === cleanU && (x.pass || '').trim() === p);
        }
      }
    } catch (e) {}
  }

  if (found) {
    if (isUserExpired(found)) {
      const expInfo = getExpiryInfo(found);
      alert('⛔ TÀI KHOẢN ĐÃ HẾT HẠN DÙNG THỬ!\n\nChào bé ' + found.name + ', tài khoản của con đã hết hạn dùng thử vào ngày ' + expInfo.dateStr + '.\n\nBa mẹ vui lòng liên hệ Thầy Nguyễn Đình Chinh (Zalo/Hotline: 0941.492.468) để gia hạn khóa học cho con nhé! ❤️');
      return;
    }
    state.currentUser = found;
    state.playerName = found.name;
    localStorage.setItem('mathquiz_current_user', JSON.stringify(found));
    localStorage.setItem('mathquiz_name', found.name);
    state.screen = 'home';
    render();
  } else {
    const err = document.getElementById('loginError');
    if (err) err.style.display = 'block';
  }
}

