const fs = require('fs');

function checkGrade(gNum, xmlPath, maxPages) {
  const xml = fs.readFileSync(xmlPath, 'utf8');
  const pageRegex = /<page\s+number="(\d+)"[^>]*>([\s\S]*?)<\/page>/g;
  let m;
  const pageMap = {};

  while ((m = pageRegex.exec(xml)) !== null) {
    const pNum = parseInt(m[1], 10);
    const content = m[2];

    const textRegex = /<text\s+top="(\d+)"[^>]*>(?:<[^>]+>)*([^<]*)(?:<\/[^>]+>)*<\/text>/g;
    let tm;
    const texts = [];
    while ((tm = textRegex.exec(content)) !== null) {
      const val = tm[2].trim();
      if (val) texts.push({ top: parseInt(tm[1], 10), text: val });
    }

    const imgRegex = /<image\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"/g;
    let im;
    const images = [];
    while ((im = imgRegex.exec(content)) !== null) {
      const w = parseInt(im[3], 10);
      if (w === 133 || w === 112 || w === 30) continue;
      images.push({
        top: parseInt(im[1], 10),
        bottom: parseInt(im[1], 10) + parseInt(im[4], 10)
      });
    }

    pageMap[pNum] = { texts, images };
  }

  // Detect which questions have images across pages
  // Or where a question starts on page P and has images on page P+1 before next question starts
  let activeQ = 0;
  const qPages = {};
  for (let p = 1; p <= maxPages; p++) {
    const pData = pageMap[p];
    if (!pData) continue;

    const qStarts = [];
    pData.texts.forEach(t => {
      const qm = t.text.match(/^(\d+)\.\s+/);
      if (qm && parseInt(qm[1], 10) <= 30) {
        qStarts.push({ qNum: parseInt(qm[1], 10), top: t.top });
      }
    });

    // Check images before the first qStart on this page
    if (qStarts.length > 0) {
      const firstQ = qStarts[0];
      const preImages = pData.images.filter(img => img.top < firstQ.top);
      if (preImages.length > 0 && activeQ > 0) {
        if (!qPages[activeQ]) qPages[activeQ] = [];
        qPages[activeQ].push({ page: p, type: 'preImages', count: preImages.length });
      }
    } else if (pData.images.length > 0 && activeQ > 0) {
      if (!qPages[activeQ]) qPages[activeQ] = [];
      qPages[activeQ].push({ page: p, type: 'fullPageImages', count: pData.images.length });
    }

    if (qStarts.length > 0) {
      activeQ = qStarts[qStarts.length - 1].qNum;
    }
  }

  console.log(`Grade ${gNum} questions with orphaned images on next page:`, qPages);
}

