const fs = require('fs');

function analyzeGradeStructure(gNum, xmlPath, maxPages) {
  const xml = fs.readFileSync(xmlPath, 'utf8');
  const pageRegex = /<page\s+number="(\d+)"[^>]*>([\s\S]*?)<\/page>/g;
  let m;
  const pages = {};

  while ((m = pageRegex.exec(xml)) !== null) {
    const pNum = parseInt(m[1], 10);
    const content = m[2];

    const textRegex = /<text\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"[^>]*>(?:<[^>]+>)*([^<]*)(?:<\/[^>]+>)*<\/text>/g;
    let tm;
    const texts = [];
    while ((tm = textRegex.exec(content)) !== null) {
      const val = tm[5].trim();
      if (val) {
        texts.push({
          top: parseInt(tm[1], 10),
          left: parseInt(tm[2], 10),
          width: parseInt(tm[3], 10),
          height: parseInt(tm[4], 10),
          text: val
        });
      }
    }
    pages[pNum] = texts;
  }

  // Find all test headings (e.g. "Toán Kangaroo Lớp X - Số Y" or "Đề số Y")
  const testList = [];
  for (let p = 1; p <= maxPages; p++) {
    const texts = pages[p] || [];
    const full = texts.map(t => t.text).join(' ');
    const tm = full.match(/Số\s*0?(\d+)/i) || full.match(/Đề\s*0?(\d+)/i);
    if (full.includes('Kangaroo') || full.includes('kynaforkids') || full.includes('Pre-Ecolier') || full.includes('Ecolier') || full.includes('Benjamin')) {
      if (tm && parseInt(tm[1], 10) <= 20) {
        testList.push({ de: parseInt(tm[1], 10), page: p });
      }
    }
  }

  // Deduplicate tests
  const uniqueTests = [];
  const seenDe = new Set();
  testList.forEach(t => {
    if (!seenDe.has(t.de)) {
      seenDe.add(t.de);
      uniqueTests.push(t);
    }
  });
  uniqueTests.sort((a, b) => a.page - b.page);

  console.log(`Grade ${gNum}: found ${uniqueTests.length} tests:`, uniqueTests.map(t => `De ${t.de} (p${t.page})`).join(', '));
  return { pages, uniqueTests };
}

for (let g = 1; g <= 5; g++) {
  const maxP = [0, 93, 82, 63, 80, 55][g];
  analyzeGradeStructure(g, `C:/Users/HNBV3384/.gemini/antigravity/scratch/ikmc${g}_full.xml`, maxP);
}

