const fs = require('fs');

function getExactTestRanges(gNum) {
  const xml = fs.readFileSync(`C:/Users/HNBV3384/.gemini/antigravity/scratch/ikmc${gNum}_full.xml`, 'utf8');
  const maxP = [0, 93, 82, 63, 80, 55][gNum];

  const ranges = [];
  // For each page, check if it has a header with test number
  for (let p = 1; p <= maxP; p++) {
    const pMatch = xml.match(new RegExp(`<page\\s+number="${p}"[^>]*>([\\s\\S]*?)<\\/page>`));
    if (!pMatch) continue;
    const content = pMatch[1];

    // Check if page has title like "Toán Kangaroo Lớp X – Số Y" or "Đề thi... Số Y"
    const m = content.match(/Số\s*0?(\d+)/i);
    if (m && (content.includes('Kangaroo') || content.includes('Pre-Ecolier') || content.includes('Ecolier') || content.includes('Benjamin') || content.includes('kynaforkids'))) {
      const de = parseInt(m[1], 10);
      if (de <= 20) {
        // Only if it's in the top 200 points of the page
        const textTopMatch = content.match(/<text\s+top="(\d+)"[^>]*>[^<]*Số/i);
        if (textTopMatch && parseInt(textTopMatch[1], 10) < 200) {
          ranges.push({ de, page: p });
        }
      }
    }
  }

  // Deduplicate
  const unique = [];
  const seen = new Set();
  ranges.forEach(r => {
    if (!seen.has(r.de)) {
      seen.add(r.de);
      unique.push(r);
    }
  });
  unique.sort((a, b) => a.page - b.page);

  // Compute end pages
  for (let i = 0; i < unique.length; i++) {
    unique[i].endPage = (i + 1 < unique.length) ? unique[i + 1].page - 1 : maxP;
  }

  return unique;
}

