const allSpecs = [];

for (let gNum = 1; gNum <= 5; gNum++) {
  const xml = fs.readFileSync(`C:/Users/HNBV3384/.gemini/antigravity/scratch/ikmc${gNum}_full.xml`, 'utf8');

  // Parse all pages
  const pageRegex = /<page\s+number="(\d+)"[^>]*>([\s\S]*?)<\/page>/g;
  let m;
  const pageMap = {};

  while ((m = pageRegex.exec(xml)) !== null) {
    const pNum = parseInt(m[1], 10);
    const content = m[2];

    const textRegex = /<text\s+top="(\d+)"\s+left="(\d+)"\s+width="(\d+)"\s+height="(\d+)"[^>]*>(?:<[^>]+>)*([^<]*)(?:<\/[^>]+>)*<\/text>/g;
    let tm;
    const texts = [];
    while ((tm = textRegex.exec(content)) !== null) {
      const val = tm[5].trim();
      if (val) {
        texts.push({
          top: parseInt(tm[1], 10),
          left: parseInt(tm[2], 10),
          width: parseInt(tm[3], 10),
          height: parseInt(tm[4], 10),
          text: val
        });
      }
    }
    pageMap[pNum] = texts;
  }

  const tests = gradeTests[gNum];
  const gLetterOnly = letterOnly.filter(q => q.grade == gNum);

  tests.forEach(t => {
    const qStarts = [];
    for (let p = t.start; p <= t.end; p++) {
      const texts = pageMap[p] || [];
      texts.forEach(txt => {
        const qm = txt.text.match(/^(\d+)\.\s*/);
        if (qm) {
          const num = parseInt(qm[1], 10);
          if (num <= 30) {
            qStarts.push({ de: t.de, num, page: p, top: txt.top });
          }
        }
      });
    }

    // Deduplicate by num
    const uniqueQ = [];
    const seen = new Set();
    qStarts.forEach(q => {
      if (!seen.has(q.num)) {
        seen.add(q.num);
        uniqueQ.push(q);
      }
    });
    uniqueQ.sort((a, b) => a.num - b.num);

    for (let i = 0; i < uniqueQ.length; i++) {
      const cur = uniqueQ[i];
      const nxt = (i + 1 < uniqueQ.length) ? uniqueQ[i + 1] : null;

      const matchedQ = gLetterOnly.find(l => {
        const deMatch = l.round.match(/Số\s*0?(\d+)/i);
        const lDe = deMatch ? parseInt(deMatch[1], 10) : 0;
        return lDe === cur.de && l.num == cur.num;
      });

      if (!matchedQ) continue;

      allSpecs.push({
        id: matchedQ.id,
        grade: gNum,
        de: cur.de,
        num: cur.num,
        startPage: cur.page,
        startTop: cur.top,
        endPage: nxt ? nxt.page : cur.page,
        endTop: nxt ? nxt.top : 760,
        pageDir: `C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\ikmc${gNum}_all_pages`,
        targetFile: `images/ikmc/g${gNum}_de${cur.de}_q${cur.num.toString().padStart(2, '0')}.png`
      });
    }
  });
}

