$specsJson = Get-Content "C:\Users\HNBV3384\.gemini\antigravity\scratch\all_grades_crop_specs.json" -Raw | ConvertFrom-Json

$outBase = "C:\Users\HNBV3384\.gemini\antigravity\scratch\toan-quoc-te"

$scale = 25.0 / 12.0
$successCount = 0
$errorCount = 0

function TrimBitmap([System.Drawing.Bitmap]$bmp, [int]$searchY1, [int]$searchY2) {
    $minX = 999999
    $maxX = 0
    $minY = 999999
    $maxY = 0

    $yStart = [Math]::Max(0, $searchY1)
    $yEnd = [Math]::Min($bmp.Height - 1, $searchY2)

    for ($y = $yStart; $y -le $yEnd; $y += 2) {
        for ($x = 100; $x -lt ($bmp.Width - 100); $x += 2) {
            $p = $bmp.GetPixel($x, $y)
            if ($p.R -lt 240 -or $p.G -lt 240 -or $p.B -lt 240) {
                if ($x -lt $minX) { $minX = $x }
                if ($x -gt $maxX) { $maxX = $x }
                if ($y -lt $minY) { $minY = $y }
                if ($y -gt $maxY) { $maxY = $y }
            }
        }
    }

    if ($minX -ge $maxX -or $minY -ge $maxY) {
        return $null
    }

    $pad = 15
    $rx = [Math]::Max(0, $minX - $pad)
    $ry = [Math]::Max(0, $minY - $pad)
    $rw = [Math]::Min($bmp.Width - $rx, ($maxX - $minX) + ($pad * 2))
    $rh = [Math]::Min($bmp.Height - $ry, ($maxY - $minY) + ($pad * 2))

    $rect = [System.Drawing.Rectangle]::new($rx, $ry, $rw, $rh)
    return $bmp.Clone($rect, $bmp.PixelFormat)
}

foreach ($spec in $specsJson) {
    try {
        $outFile = Join-Path $outBase $spec.targetFile
        $outDir = [System.IO.Path]::GetDirectoryName($outFile)
        if (-not (Test-Path $outDir)) {
            [System.IO.Directory]::CreateDirectory($outDir) | Out-Null
        }

        $p1Num = "{0:D2}" -f $spec.startPage
        $p1Path = Join-Path $spec.pageDir "p-$p1Num.png"

        if (-not (Test-Path $p1Path)) {
            Write-Warning "Missing page file: $p1Path"
            $errorCount++
            continue
        }

        $bmp1 = [System.Drawing.Bitmap]::FromFile($p1Path)

        if ($spec.startPage -eq $spec.endPage) {
            # Single page crop
            $y1 = [int]($spec.startTop * $scale)
            $y2 = [int]($spec.endTop * $scale)

            # Skip the question prompt text itself (approx 40-70px) if we want just diagram+options,
            # or include it from y1. Starting at y1 + 30 skips the "1. Hình nào..." title line.
            $crop = TrimBitmap $bmp1 ($y1 + 25) ($y2 - 10)
            if ($null -eq $crop) {
                # Fallback to full range
                $crop = TrimBitmap $bmp1 $y1 $y2
            }

            if ($null -ne $crop) {
                $crop.Save($outFile, [System.Drawing.Imaging.ImageFormat]::Png)
                $crop.Dispose()
                $successCount++
            } else {
                Write-Warning "Could not find content for $($spec.id)"
                $errorCount++
            }
        } else {
            # Multi-page crop (splits across page 1 and page 2)
            $y1 = [int]($spec.startTop * $scale)
            $crop1 = TrimBitmap $bmp1 ($y1 + 25) ($bmp1.Height - 1)
            if ($null -eq $crop1) {
                $crop1 = TrimBitmap $bmp1 $y1 ($bmp1.Height - 1)
            }

            $p2Num = "{0:D2}" -f $spec.endPage
            $p2Path = Join-Path $spec.pageDir "p-$p2Num.png"
            $bmp2 = [System.Drawing.Bitmap]::FromFile($p2Path)

            $y2 = [int]($spec.endTop * $scale)
            # On second page, options start near top (skip page header 100px) down to next Q
            $crop2 = TrimBitmap $bmp2 80 ($y2 - 10)
            if ($null -eq $crop2) {
                $crop2 = TrimBitmap $bmp2 50 $y2
            }

            if ($null -ne $crop1 -and $null -ne $crop2) {
                # Determine stitch layout:
                # If both are narrow (width < 600), stitch side-by-side
                if (($crop1.Width + $crop2.Width) -lt 1100) {
                    $sw = $crop1.Width + $crop2.Width + 40
                    $sh = [Math]::Max($crop1.Height, $crop2.Height) + 20
                    $stitched = [System.Drawing.Bitmap]::new($sw, $sh)
                    $g = [System.Drawing.Graphics]::FromImage($stitched)
                    $g.Clear([System.Drawing.Color]::White)
                    $g.DrawImage($crop1, 10, [int](($sh - $crop1.Height)/2))
                    $g.DrawImage($crop2, $crop1.Width + 30, [int](($sh - $crop2.Height)/2))
                    $g.Dispose()
                    $stitched.Save($outFile, [System.Drawing.Imaging.ImageFormat]::Png)
                    $stitched.Dispose()
                } else {
                    # Stack vertically
                    $sw = [Math]::Max($crop1.Width, $crop2.Width) + 20
                    $sh = $crop1.Height + $crop2.Height + 30
                    $stitched = [System.Drawing.Bitmap]::new($sw, $sh)
                    $g = [System.Drawing.Graphics]::FromImage($stitched)
                    $g.Clear([System.Drawing.Color]::White)
                    $g.DrawImage($crop1, [int](($sw - $crop1.Width)/2), 10)
                    $g.DrawImage($crop2, [int](($sw - $crop2.Width)/2), $crop1.Height + 20)
                    $g.Dispose()
                    $stitched.Save($outFile, [System.Drawing.Imaging.ImageFormat]::Png)
                    $stitched.Dispose()
                }
                $successCount++
            } elseif ($null -ne $crop1) {
                $crop1.Save($outFile, [System.Drawing.Imaging.ImageFormat]::Png)
                $successCount++
            } elseif ($null -ne $crop2) {
                $crop2.Save($outFile, [System.Drawing.Imaging.ImageFormat]::Png)
                $successCount++
            } else {
                Write-Warning "Could not crop multi-page $($spec.id)"
                $errorCount++
            }

            if ($null -ne $crop1) { $crop1.Dispose() }
            if ($null -ne $crop2) { $crop2.Dispose() }
            $bmp2.Dispose()
        }

        $bmp1.Dispose()
    } catch {
        Write-Warning "Error processing $($spec.id): $_"
        $errorCount++
    }
}

Write-Output "FINISHED! Successfully cropped: $successCount, Errors: $errorCount"

