const fs = require('fs');

function checkGrade(filePath, grade) {
  const content = fs.readFileSync(filePath, 'utf8');
  console.log(`\n================ GRADE ${grade}: ${filePath.split('/').pop()} ================`);

  const solHeaderIdx = content.search(/HƯỚNG DẪN GIẢI/i);
  const probSection = content.substring(0, solHeaderIdx);
  const solSection = content.substring(solHeaderIdx);

  const chaps = probSection.split(/<div class="chapter-header">/);
  console.log('Chapters found:', chaps.length - 1);
  for (let i = 1; i < chaps.length; i++) {
    const part = chaps[i];
    const title = part.substring(0, part.indexOf('</div>')).trim();
    const probNums = [];
    const re = /<span class="problem-num">Bài\s*(\d+):<\/span>/g;
    let m;
    while ((m = re.exec(part)) !== null) probNums.push(parseInt(m[1], 10));
    console.log(`  ${title}: Bài ${probNums[0]} -> Bài ${probNums[probNums.length - 1]} (${probNums.length} bài)`);
  }
}

checkGrade('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_1/toan_nang_cao_lop_1_chuan.html', 1);
checkGrade('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_2/toan_nang_cao_lop_2_chuan.html', 2);
checkGrade('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_3/toan_nang_cao_lop_3_chuan.html', 3);
checkGrade('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_5/tap_1_so_hoc_va_ti_so_phan_tram.html', 5);
checkGrade('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_5/tap_2_hinh_hoc_va_chuyen_dong.html', 5);

const fs = require('fs');

function generateAcceptedAnswers(ans) {
  const set = new Set();
  if (!ans) return [];
  const a = ans.trim();
  set.add(a);

  // Strip units
  const numOnlyMatch = a.match(/^([\d.,]+)\s*(chữ số|số|ghế|học sinh|quyển|viên|con|tuổi|gói|hộp|đồng|m²|cm²|dm²|m|cm|km|phút|giờ|giây|trận|quân bài|kg|g|tấn|tạ|yến|ngày|lần|đoạn|bạn|bông|cây|quả|bút|cái)?$/i);
  if (numOnlyMatch) {
    const rawNum = numOnlyMatch[1].replace(/[.,]/g, '');
    const formattedNum = numOnlyMatch[1];
    set.add(rawNum);
    set.add(formattedNum);
    // Also support dot/comma decimal swap if has comma
    if (formattedNum.includes(',')) set.add(formattedNum.replace(',', '.'));
    if (formattedNum.includes('.')) set.add(formattedNum.replace('.', ','));
    if (numOnlyMatch[2]) {
      set.add(`${rawNum} ${numOnlyMatch[2]}`);
      set.add(`${formattedNum} ${numOnlyMatch[2]}`);
    }
  }

  // Handle multiple values separated by ; or ,
  if (a.includes(';') || a.includes(',')) {
    const parts = a.split(/[;,]/).map(p => p.trim());
    set.add(parts.join('; '));
    set.add(parts.join(', '));
    set.add(parts.join(' và '));
    set.add(parts.join(' '));
    // Also extract raw numbers from parts if applicable
    const nums = parts.map(p => {
      const m = p.match(/[\d.,]+/);
      return m ? m[0] : p;
    });
    set.add(nums.join('; '));
    set.add(nums.join(', '));
    set.add(nums.join(' '));
  }

  // Handle fraction format
  if (a.includes('/')) {
    set.add(a.replace(/\s+/g, ''));
  }

  // Lowercase / non-accent variations for common words
  if (/không thể/i.test(a)) {
    set.add('không thể');
    set.add('khong the');
    set.add('không');
    set.add('khong');
  }
  if (/có/i.test(a)) {
    set.add('có');
    set.add('co');
  }

  return Array.from(set);
}

function parseFile(filePath, grade, fileLabel) {
  const content = fs.readFileSync(filePath, 'utf8');
  const solHeaderIdx = content.search(/HƯỚNG DẪN GIẢI/i);
  const probContent = content.substring(0, solHeaderIdx);
  const solContent = content.substring(solHeaderIdx);

  const solMap = {};
  const solRegex = /<div class="sol-item"><span class="sol-num">Bài\s*(\d+):<\/span>([\s\S]*?)<\/div>/g;
  let sm;
  while ((sm = solRegex.exec(solContent)) !== null) {
    const num = parseInt(sm[1], 10);
    const body = sm[2].trim();
    const strongMatch = body.match(/<strong>(.*?)<\/strong>/g);
    let extractedAns = '';
    if (strongMatch) {
      extractedAns = strongMatch.map(s => s.replace(/<\/?strong>/g, '').trim()).join('; ');
    }
    solMap[num] = {
      ans: extractedAns,
      cleanText: body.replace(/<[^>]+>/g, '').trim()
    };
  }

  // Manual fixes for edge cases where <strong> was missing or formatted differently
  if (grade === 3 && solMap[17] && !solMap[17].ans) {
    solMap[17].ans = "48; 12";
  }
  if (grade === 5 && solMap[30] && !solMap[30].ans) {
    solMap[30].ans = "24,8; 28; 14";
  }

  const questions = [];
  const chapterSplits = probContent.split(/<div class="chapter-header">/);
  for (let c = 1; c < chapterSplits.length; c++) {
    const part = chapterSplits[c];
    const chapTitle = part.substring(0, part.indexOf('</div>')).trim();
    const roundName = chapTitle.replace(/^CHỦ ĐỀ\s*/i, 'Chuyên đề ');
    const topicName = chapTitle.replace(/^CHỦ ĐỀ\s*\d+\s*:\s*/i, '');

    const probRegex = /<div class="problem-item"><span class="problem-num">Bài\s*(\d+):<\/span>([\s\S]*?)<\/div>/g;
    let pm;
    while ((pm = probRegex.exec(part)) !== null) {
      const num = parseInt(pm[1], 10);
      const probText = pm[2].replace(/<[^>]+>/g, '').trim();
      const sol = solMap[num];
      const ans = sol ? sol.ans : '';
      const exp = sol ? sol.cleanText : '';

      const accepted = generateAcceptedAnswers(ans);
      if (grade === 3 && num === 17) {
        accepted.push('48', '48 con gà, 12 con vịt', '48 và 12', '44; 11', '12; 48');
      }
      if (grade === 5 && num === 30) {
        accepted.push('24.8; 28; 14', '24.8, 28, 14', '24,8, 28, 14', '14; 28; 24,8', '14; 28; 24.8');
      }

      questions.push({
        id: `T365-G${grade}-${String(num).padStart(3, '0')}`,
        exam: "TOAN_365",
        grade: grade,
        round: roundName,
        topic: topicName,
        num: num,
        text: `Bài ${num}. ${probText}`,
        type: "fill",
        answer: ans,
        acceptedAnswers: accepted,
        explanation: exp
      });
    }
  }

  return questions;
}

const g1 = parseFile('V:/ChinhND/Đề ôn tập/toan_nang_cao_lop_1/toan_nang_cao_lop_1_chuan.html', 1, 'G1');
