// ===== HỆ THỐNG BẢO LƯU TIẾN ĐỘ & QUẢN LÝ BÀI TẬP ĐÃ LÀM =====
function getUserKey() {
  return state.currentUser ? (state.currentUser.username || 'user') : (state.playerName || 'guest');
}

function getInProgressMap() {
  try {
    const raw = localStorage.getItem('mathquiz_in_progress_' + getUserKey());
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function setInProgressMap(map) {
  try {
    localStorage.setItem('mathquiz_in_progress_' + getUserKey(), JSON.stringify(map));
  } catch (e) {}
}

function getSavedSession(grade, exam, round) {
  const map = getInProgressMap();
  const key = `${grade}__${exam}__${round}`;
  return map[key] || null;
}

function saveCurrentQuizProgress() {
  if (state.screen !== 'quiz' || !state.questions || state.questions.length === 0) return;
  const map = getInProgressMap();
  const key = `${state.selectedGrade}__${state.selectedExam}__${state.selectedRound}`;
  map[key] = {
    username: getUserKey(),
    playerName: state.playerName,
    grade: state.selectedGrade,
    exam: state.selectedExam,
    round: state.selectedRound,
    customMinutes: state.customMinutes,
    questions: state.questions,
    answers: state.answers || {},
    currentQuestion: state.currentQuestion || 0,
    timeLeft: state.timeLeft,
    quizStartTime: state.quizStartTime,
    savedAt: new Date().toISOString()
  };
  setInProgressMap(map);
}

function clearSavedSession(grade, exam, round) {
  const map = getInProgressMap();
  const key = `${grade}__${exam}__${round}`;
  if (map[key]) {
    delete map[key];
    setInProgressMap(map);
  }
}

function getCompletedRecord(grade, exam, round) {
  try {
    const history = JSON.parse(localStorage.getItem('mathquiz_history') || '[]');
    const uKey = getUserKey();
    return history.find(h => {
      const matchUser = (h.username ? h.username === uKey : true);
      return matchUser && String(h.grade) === String(grade) && h.exam === exam && h.round === round;
    }) || null;
  } catch (e) {
    return null;
  }
}

function getCompletedRoundsMap(grade, exam) {
  try {
    const history = JSON.parse(localStorage.getItem('mathquiz_history') || '[]');
    const uKey = getUserKey();
    const map = {};
    history.forEach(h => {
      const matchUser = (h.username ? h.username === uKey : true);
      if (matchUser && String(h.grade) === String(grade) && h.exam === exam && h.round) {
        if (!map[h.round] || (h.score > map[h.round].score)) {
          map[h.round] = h;
        }
      }
    });
    return map;
  } catch (e) {
    return {};
  }
}

function pauseAndSaveQuiz() {
  if (confirm('Con có muốn tạm dừng và lưu lại bài làm để lần sau làm tiếp không?\n\n(Toàn bộ câu trả lời và thời gian còn lại sẽ được bảo lưu nguyên vẹn)')) {
    saveCurrentQuizProgress();
    clearInterval(state.timerInterval);
    alert('✅ Đã lưu bài làm thành công!\nKhi con quay lại, con có thể tiếp tục làm ngay từ chỗ đã dừng nhé.');
    showScreen('home');
  }
}

function resumeSavedQuiz() {
  const session = state.resumeModal ? state.resumeModal.session : null;
  state.resumeModal = null;
  if (!session) return;
  state.selectedGrade = session.grade;
  state.selectedExam = session.exam;
  state.selectedRound = session.round;
  state.customMinutes = session.customMinutes;
  state.questions = session.questions;
  state.answers = session.answers || {};
  state.currentQuestion = session.currentQuestion || 0;
  state.timeLeft = session.timeLeft;
  state.quizStartTime = session.quizStartTime || Date.now();
  state.screen = 'quiz';

  clearInterval(state.timerInterval);
  if (state.customMinutes > 0) {
    let tick = 0;
    state.timerInterval = setInterval(() => {
      state.timeLeft--;
      tick++;
      if (tick % 3 === 0) saveCurrentQuizProgress();
      const el = document.getElementById('timer');
      if (el) {
        const m = Math.floor(state.timeLeft / 60);
        const s = state.timeLeft % 60;
        el.textContent = `⏱️ ${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
      }
      if (state.timeLeft <= 0) {
        clearInterval(state.timerInterval);
        submitQuiz();
      }
    }, 1000);
  }
  render();
}

function quickResumeSession(grade, exam, round) {
  const s = getSavedSession(grade, exam, round);
  if (s) {
    state.resumeModal = { type: 'in_progress', session: s };
    resumeSavedQuiz();
  }
}

function discardAndStartFresh() {
  state.resumeModal = null;
