saveCurrentQuizProgress();
const session = getSavedSession(4, 'TOAN_365', 'Chuyên đề 1: Dãy số');
console.log('Saved session found:', !!session, 'Answers:', session.answers, 'TimeLeft:', session.timeLeft);

console.log('--- TEST 2: Completing quiz ---');
clearSavedSession(4, 'TOAN_365', 'Chuyên đề 1: Dãy số');
const afterClear = getSavedSession(4, 'TOAN_365', 'Chuyên đề 1: Dãy số');
console.log('Session cleared:', afterClear === null);

