const fs = require('fs');
const path = require('path');

const KANGAROO_FILE = 'C:/Users/HNBV3384/.gemini/antigravity/scratch/toan-quoc-te/kangaroo_data.js';

function mergeSolutions() {
  console.log('Reading current kangaroo_data.js...');
  const code = fs.readFileSync(KANGAROO_FILE, 'utf8');
  const prefix = 'const KANGAROO_DB = ';
  const startIdx = code.indexOf(prefix);
  const jsonStr = code.substring(startIdx + prefix.length).replace(/;[\s\r\n]*$/, '');
  const db = JSON.parse(jsonStr);

  const files = [
    { grade: 'grade1', path: 'C:/Users/HNBV3384/.gemini/antigravity/scratch/g1_solved.json' },
    { grade: 'grade2', path: 'C:/Users/HNBV3384/.gemini/antigravity/scratch/g2_solved.json' },
    { grade: 'grade3', path: 'C:/Users/HNBV3384/.gemini/antigravity/scratch/g3_de5_7_solved.json', partial: true },
    { grade: 'grade5', path: 'C:/Users/HNBV3384/.gemini/antigravity/scratch/g5_solved.json' }
  ];

  let totalUpdated = 0;

  files.forEach(({ grade, path: fpath, partial }) => {
    if (!fs.existsSync(fpath)) {
      console.log(`[WAITING] File not ready yet: ${fpath}`);
      return;
    }
    const solved = JSON.parse(fs.readFileSync(fpath, 'utf8'));
    console.log(`Loaded ${solved.length} solved questions from ${fpath}`);

    if (partial) {
      // Update by question id
      const map = {};
      solved.forEach(q => { map[q.id] = q; });
      db[grade].forEach(q => {
        if (map[q.id]) {
          q.answer = map[q.id].answer;
          q.acceptedAnswers = map[q.id].acceptedAnswers || [map[q.id].answer, map[q.id].answer.toLowerCase()];
          q.explanation = map[q.id].explanation;
          if (map[q.id].options && map[q.id].options.length > 0) q.options = map[q.id].options;
          totalUpdated++;
        }
      });
    } else {
      // Replace or update questions
      const map = {};
      solved.forEach(q => { map[q.id] = q; });
      db[grade].forEach(q => {
        if (map[q.id]) {
          q.answer = map[q.id].answer;
          q.acceptedAnswers = map[q.id].acceptedAnswers || [map[q.id].answer, map[q.id].answer.toLowerCase()];
          q.explanation = map[q.id].explanation;
          if (map[q.id].options && map[q.id].options.length > 0) q.options = map[q.id].options;
          totalUpdated++;
        }
      });
    }
  });

  console.log(`Total questions updated so far: ${totalUpdated}`);

  // Re-verify generic explanation count
  let remainingGeneric = 0;
  Object.keys(db).forEach(g => {
    db[g].forEach(q => {
      const exp = q.explanation || '';
      if (exp.includes('Đọc kỹ đề bài, quan sát hình ảnh minh họa và áp dụng tư duy trực quan')) {
        remainingGeneric++;
      }
    });
  });
  console.log(`Remaining generic/dummy explanations across entire DB: ${remainingGeneric}`);

  const out = '/**\n * BỘ ĐỀ THI TOÁN QUỐC TẾ KANGAROO (IKMC) CHUẨN LỚP 1, 2, 3, 4, 5\n * Trọn bộ 37 Đề thi tuyển chọn kèm 100% hình ảnh minh họa gốc chuẩn xác\n */\n\nconst KANGAROO_DB = ' + JSON.stringify(db, null, 2) + ';\n';
  fs.writeFileSync(KANGAROO_FILE, out);
  console.log('Saved updated kangaroo_data.js.');
}

mergeSolutions();

