// Utility helper for Archimedes Tiếng Việt database generation
function makeQ(id, grade, round, topic, text, options, answer, explanation) {
  if (!['A', 'B', 'C', 'D'].includes(answer)) {
    throw new Error(`Invalid answer ${answer} for question ${id}`);
  }
  if (!options || options.length !== 4) {
    throw new Error(`Options must have exactly 4 items for question ${id}`);
  }
  return {
    id,
    exam: "TIENG_VIET",
    grade,
    round,
    topic,
    text: text.trim(),
    question: text.trim(),
    options: options.map(o => o.trim()),
    answer,
    explanation: explanation.trim()
  };
}

module.exports = { makeQ };

const { makeQ } = require('./tv_builder_utils');
