function generateGrade1() {
  const list = [];
  const existingW1 = existingDb['1'] || [];

  TV1_SYLLABUS.forEach(weekInfo => {
    const w = weekInfo.w;
    const topic = weekInfo.title;

    // Các round trong tuần
    const rounds = [
      { name: `Tuần ${w} - Tiết 1`, code: 'T1' },
      { name: `Tuần ${w} - Tiết 2`, code: 'T2' },
      { name: `Tuần ${w} - Tiết 3`, code: 'T3' },
      { name: `Tuần ${w} - Phiếu cuối tuần`, code: 'PKT' },
      { name: `Tuần ${w} - Bài tập tham khảo`, code: 'TTK' }
    ];

    rounds.forEach(r => {
      // Nếu là tuần 1 và có câu hỏi gốc đã lưu, dùng câu hỏi gốc
      if (w === 1) {
        const found = existingW1.filter(q => q.round === r.name);
        if (found.length > 0) {
          found.forEach(q => list.push(q));
          return;
        }
      }

      // Tạo 3 câu hỏi độc nhất, phong phú, bám sát âm vần tuần đó
      if (w === 2) {
        if (r.code === 'T1') {
          list.push(makeQ(`TV-G1-W${w}-${r.code}-1`, 1, r.name, topic,
            "Tiếng nào dưới đây có chứa âm 'e'?",
            ["A. xe ve", "B. cá bống", "C. quả mơ", "D. nơ đỏ"],
            "A", "Tiếng 'xe' và 've' đều chứa âm 'e'."));
          list.push(makeQ(`TV-G1-W${w}-${r.code}-2`, 1, r.name, topic,
            "Tiếng nào dưới đây có âm đầu là 'đ'?",
            ["A. đi bộ", "B. cô giáo", "C. lá đa (tiếng đa)", "D. Cả A và C đều đúng"],
            "D", "Tiếng 'đi' và tiếng 'đa' đều có âm đầu là 'đ'."));
          list.push(makeQ(`TV-G1-W${w}-${r.code}-3`, 1, r.name, topic,
            "Điền âm 'd' hay 'đ' vào chỗ trống: '...àn gà con lon ton'?",
            ["A. đ", "B. d", "C. k", "D. c"],
            "A", "Từ đúng là 'đàn gà'."));
        } else if (r.code === 'T2') {
          list.push(makeQ(`TV-G1-W${w}-${r.code}-1`, 1, r.name, topic,
            "Trong các từ sau, từ nào có tiếng mang thanh hỏi?",
            ["A. củ sả", "B. lá cờ", "C. mẹ yêu", "D. cá rô"],
            "A", "Tiếng 'củ' và 'sả' đều mang thanh hỏi."));
          list.push(makeQ(`TV-G1-W${w}-${r.code}-2`, 1, r.name, topic,
            "Tiếng nào dưới đây có chứa âm 'ê'?",
