          "A", `Hình ảnh nhân hóa mang lại sự ấm cúng, thân thuộc của thiên nhiên vũ trụ bao la.`));
        list.push(makeQ(`TV-G3-W${w}-${r.code}-3`, 3, r.name, topic,
          `Lời khuyên nào dưới đây đúc kết sâu sắc nhất tinh thần học tập và rèn luyện của học sinh lớp 3 Archimedes?`,
          [`A. Luôn chủ động, sáng tạo, giàu lòng nhân ái và tự giác vươn lên trong học tập`, `B. Học vẹt để nhớ chữ mà không hiểu nghĩa`, `C. Làm bài qua loa cho xong việc`, `D. Chỉ học khi có người lớn nhắc nhở`],
          "A", `Tinh thần học tập chủ động, sáng tạo và nhân ái là mục tiêu cốt lõi của học sinh Archimedes.`));
      }
    });
  });

  return list;
}

