          [`A. Quan sát bằng nhiều giác quan, chọn lọc chi tiết tiêu biểu và vận dụng sáng tạo phép so sánh, nhân hóa`, `B. Liệt kê kích thước số đo cơ học mà không tả hình dáng`, `C. Chỉ chép lại văn mẫu của người khác`, `D. Không dùng tính từ miêu tả`],
          "A", `Quan sát tinh tế và dùng biện pháp tu từ so sánh, nhân hóa giúp bài văn miêu tả trở nên sống động, có hồn.`));
        list.push(makeQ(`TV-G4-W${w}-${r.code}-3`, 4, r.name, topic,
          `Câu tục ngữ nào dưới đây ca ngợi ý chí, nghị lực vượt khó vươn lên trong cuộc sống?`,
          [`A. Có chí thì nên / Lửa thử vàng, gian nan thử sức`, `B. Nước chảy hoa trôi`, `C. Gió chiều nào che chiều ấy`, `D. Đục nước béo cò`],
          "A", `'Có chí thì nên' khẳng định người có ý chí, quyết tâm thì việc gì cũng thành công.`));
      }
    });
  });

  return list;
}

