const fs = require('fs');
const html = fs.readFileSync('C:/Users/HNBV3384/.gemini/antigravity/scratch/toan-quoc-te/ttt2_site.html', 'utf8');

const regex = /<a[^>]+href=["'](https?:\/\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
const rawIssues = [];
while ((m = regex.exec(html)) !== null) {
  const url = m[1];
  const text = m[2].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  if (url.includes('drive.google.com') && text.length > 5) {
    rawIssues.push({ url, text });
  }
}

// Clean and parse metadata (Issue number, Month, Year)
const cleanIssues = rawIssues.map(it => {
  const text = it.text;
  const numMatch = text.match(/số\s*(\d+[\+\d]*)/i);
  const monthMatch = text.match(/tháng\s*(\d+[\+\d]*)/i);
  const yearMatch = text.match(/năm\s*(\d{4})/i);

  const issueNum = numMatch ? numMatch[1] : '';
  const month = monthMatch ? monthMatch[1] : '';
  const year = yearMatch ? parseInt(yearMatch[1], 10) : 0;

  // Transform drive view url to direct preview/embed if needed
  let viewUrl = it.url;
  // If drive.google.com/file/d/ID/view, can also embed
  const idMatch = viewUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
  const fileId = idMatch ? idMatch[1] : '';

  return {
    title: text,
    issueNum: issueNum || 'Khác',
    month: month || '',
    year: year || 2015,
    url: viewUrl,
    fileId
  };
});

// Sort by issue number or year desc
cleanIssues.sort((a, b) => {
  const na = parseInt(a.issueNum, 10) || 0;
  const nb = parseInt(b.issueNum, 10) || 0;
  if (na !== nb) return nb - na; // latest first
  return (b.year || 0) - (a.year || 0);
});

console.log('Total extracted clean issues:', cleanIssues.length);
console.log('Sample parsed:', cleanIssues.slice(0, 8));

fs.writeFileSync('C:/Users/HNBV3384/.gemini/antigravity/scratch/toan-quoc-te/toan_tuoi_tho_data.js', 
  'const TOAN_TUOI_THO_DB = ' + JSON.stringify(cleanIssues, null, 2) + ';\n\nif (typeof window !== "undefined") { window.TOAN_TUOI_THO_DB = TOAN_TUOI_THO_DB; }\nif (typeof module !== "undefined" && module.exports) { module.exports = { TOAN_TUOI_THO_DB }; }\n', 
  'utf8');

console.log('Saved to toan_tuoi_tho_data.js successfully!');

