const fs = require('fs');
const html = fs.readFileSync('C:/Users/HNBV3384/.gemini/antigravity/scratch/toan-quoc-te/ttt2_site.html', 'utf8');

const regex = /<a[^>]+href=["'](https?:\/\/drive\.google\.com[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
const issues = [];
const seen = new Set();

while ((m = regex.exec(html)) !== null) {
  const url = m[1];
  const text = m[2].replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  if (text.length > 5 && !seen.has(url)) {
    seen.add(url);

    // Extract issue, month, year
    const numMatch = text.match(/số\s*(\d+[\+\&]*\d*)/i);
    const monthMatch = text.match(/tháng\s*(\d+[\+\&]*\d*)/i);
    const yearMatch = text.match(/năm\s*(\d{4})/i);

    const issueNum = numMatch ? numMatch[1] : '';
    const month = monthMatch ? monthMatch[1] : '';
    const year = yearMatch ? parseInt(yearMatch[1], 10) : (text.match(/20\d\d/) ? parseInt(text.match(/20\d\d/)[0], 10) : 0);

    const idMatch = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
    const fileId = idMatch ? idMatch[1] : '';

    issues.push({
      title: text,
      issueNum: issueNum || 'Khác',
      month: month || '',
      year: year || 2015,
      url: url,
      fileId: fileId
    });
  }
}

// Sort by issue number desc
issues.sort((a, b) => {
  const na = parseInt(a.issueNum, 10) || 0;
  const nb = parseInt(b.issueNum, 10) || 0;
  if (na !== nb) return nb - na;
  return (b.year || 0) - (a.year || 0);
});

console.log('Total unique extracted issues:', issues.length);
issues.forEach((it, i) => console.log(`${i+1}. [Số ${it.issueNum} - T${it.month}/${it.year}] ${it.title}`));

