// Tự động trích xuất và liên kết trực tiếp đến file Google Drive

const TOAN_TUOI_THO_DB = ${JSON.stringify(issues, null, 2)};

if (typeof window !== 'undefined') {
  window.TOAN_TUOI_THO_DB = TOAN_TUOI_THO_DB;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TOAN_TUOI_THO_DB };
}
`;

