        <!-- MODAL XEM FILE PDF TRỰC TIẾP -->
        <div id="magazineModal" style="display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(15,23,42,0.8);backdrop-filter:blur(6px);z-index:999999;align-items:center;justify-content:center;padding:16px;">
