const fs = require('fs');

const dataFile = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\toan-quoc-te\\timo_data.js';
let content = fs.readFileSync(dataFile, 'utf8');

// Replace "const TIMO_DB =" with module.exports
const sandbox = {};
try {
  const code = content.replace('const TIMO_DB =', 'module.exports =');
  const modPath = 'C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\tools\\temp_timo.js';
  fs.writeFileSync(modPath, code, 'utf8');
  const timoDb = require(modPath);

  console.log("TIMO_DB loaded successfully. Grades present:", Object.keys(timoDb));

  let issues = [];
  let totalQuestions = 0;

  for (let gradeKey of Object.keys(timoDb)) {
    let list = timoDb[gradeKey];
    if (!Array.isArray(list)) continue;
    totalQuestions += list.length;

    list.forEach((q, idx) => {
      let qIssues = [];
      let text = q.text || '';
      let expl = q.explanation || '';
      let img = q.image;

      // 1. PUA / font corruption
      let puaMatch = text.match(/[\uE000-\uF8FF\uFFF0-\uFFFF\uD800-\uDFFF]/g) || expl.match(/[\uE000-\uF8FF\uFFF0-\uFFFF\uD800-\uDFFF]/g);
      if (puaMatch) {
        qIssues.push(`PUA corrupted chars: ${JSON.stringify(puaMatch.slice(0, 5))}`);
      }

      // 2. Figure / image missing
      let mentionsFigure = /figure below|hình vẽ dưới đây|hình dưới đây|as shown below|như hình vẽ|pattern shown below/i.test(text);
      if (mentionsFigure && !img && !text.includes('data:image') && !text.includes('<svg') && !text.includes('●') && !text.includes('■') && !text.includes('▲')) {
        // Some pattern questions have text inline like ●□○, so check if inline symbols exist
        qIssues.push(`Mentions figure/pattern but no image or inline graphic`);
      }

      // 3. Explanation mismatch
      // Let's check common geometry keywords:
      let qHasSquare = /square|hình vuông/i.test(text);
      let explHasOnlyTriangles = /tam giác/i.test(expl) && !/vuông/i.test(expl);
      let explHasOnlyCircles = /hình tròn/i.test(expl) && !/vuông/i.test(expl);
      if (qHasSquare && (explHasOnlyTriangles || explHasOnlyCircles)) {
        qIssues.push(`Mismatch: Question asks for square, but explanation talks about ${explHasOnlyTriangles ? 'tam giác' : 'hình tròn'}`);
      }

      // Pattern alphabet vs symbols
      let qHasAlphabet = /[A-Z]、\s*[A-Z]/.test(text) || /alphabet|chữ cái/i.test(text);
      let explHasAlphabet = /chữ cái|bảng chữ cái/i.test(expl);
      if (!qHasAlphabet && explHasAlphabet && (text.includes('group') || text.includes('nhóm'))) {
        qIssues.push(`Mismatch: Question is not about alphabet, but explanation is about alphabet/chữ cái`);
      }

      // 4. Missing answer
      if (!q.answer || q.answer.toString().trim() === '') {
        qIssues.push(`Missing answer`);
      }

      if (qIssues.length > 0) {
        issues.push({
          gradeKey,
          idx,
          id: q.id,
          round: q.round,
          num: q.num,
          topic: q.topic,
          issues: qIssues,
          text: text.substring(0, 100).replace(/\n/g, ' '),
          explSnippet: expl.substring(0, 100).replace(/\n/g, ' ')
        });
      }
    });
  }

  console.log(`Total questions scanned: ${totalQuestions}`);
  console.log(`Total issues found: ${issues.length}`);

  fs.writeFileSync('C:\\Users\\HNBV3384\\.gemini\antigravity\\scratch\\tools\\timo_audit_result.json', JSON.stringify(issues, null, 2), 'utf8');

  // Print first 20 issues
  issues.slice(0, 20).forEach((iss, i) => {
    console.log(`[${i+1}] Grade: ${iss.gradeKey} | ID: ${iss.id} | Topic: ${iss.topic}`);
    console.log(`    Issues: ${iss.issues.join('; ')}`);
    console.log(`    Text: ${iss.text}`);
    console.log(`    Expl: ${iss.explSnippet}`);
  });

} catch (e) {
  console.error("Error auditing:", e);
}

