const db = require('./temp_timo.js');
const issues = require('./timo_audit_result.json');

const detailed = issues.filter(i => 
  i.issues.some(x => x.startsWith('PUA') || x.startsWith('Mismatch'))
);

console.log('Detailed count:', detailed.length);
detailed.forEach((d, i) => {
  const q = db[d.gradeKey][d.idx];
  console.log('====================================================');
  console.log('[' + (i+1) + '] Grade: ' + d.gradeKey + ' | ID: ' + q.id + ' | Round: ' + q.round + ' | Num: ' + q.num);
  console.log('Issues:', d.issues);
  console.log('Text:\n' + q.text);
  console.log('Answer:', q.answer);
  console.log('Expl:\n' + q.explanation);
});

const fs = require('fs');

function loadTimoText(grade) {
  const p = `C:\\Users\\HNBV3384\\.gemini\\antigravity\\scratch\\layout_texts\\TIMO_${grade}.txt`;
  return fs.readFileSync(p, 'utf8');
}

// Check Grade 1:
// 1) 1-Vong quoc gia - De so 6-5
// 2) 1-Vong quoc gia - De so 2-17
// 3) 1-Vong quoc gia - De so 6-18
// 4) 1-Vong quoc gia - De so 5-5
// 5) 1-Vong loai - De so 2-16

const t1 = loadTimoText(1);

function findQuestion(text, roundStr, qNum) {
  // Find round
  let rIdx = text.indexOf(roundStr);
  if (rIdx === -1) {
    console.log(`Round ${roundStr} not found`);
    return null;
  }
  // Find question number
  let qPattern = new RegExp(`(?:^|\\n)\\s*${qNum}\\.\\s+`, 'g');
  qPattern.lastIndex = rIdx;
  let match = qPattern.exec(text);
  if (!match) {
    console.log(`Q${qNum} not found in ${roundStr}`);
    return null;
  }
  let qStart = match.index;
  // find next question or end
  let nextMatch = new RegExp(`(?:^|\\n)\\s*${qNum + 1}\\.\\s+`, 'g');
  nextMatch.lastIndex = qStart + 10;
  let nMatch = nextMatch.exec(text);
  let qEnd = nMatch ? nMatch.index : qStart + 600;
  return text.substring(qStart, qEnd).trim();
}

