const categories = {};
missingImg.forEach(m => {
  const q = db[m.gradeKey][m.idx];
  let cat = 'Other';
  let t = q.text.toLowerCase();
  if (t.includes('pattern') || t.includes('quy luật') || t.includes('sequence')) cat = 'Pattern / Sequence';
  else if (t.includes('square') || t.includes('hình vuông')) cat = 'Count Squares';
  else if (t.includes('rectangle') || t.includes('hình chữ nhật')) cat = 'Count Rectangles';
  else if (t.includes('triangle') || t.includes('tam giác')) cat = 'Count Triangles';
  else if (t.includes('cube') || t.includes('lập phương')) cat = 'Cubes';
  else if (t.includes('line segment') || t.includes('đoạn thẳng')) cat = 'Line Segments';
  else if (t.includes('polygon') || t.includes('đa giác') || t.includes('side') || t.includes('cạnh')) cat = 'Polygon / Sides / Angles';
  else if (t.includes('path') || t.includes('đường đi') || t.includes('walk') || t.includes('way')) cat = 'Paths / Combinatorics';

  categories[cat] = (categories[cat] || 0) + 1;
});

console.log('Categories:', categories);

