// 4. Parse transcript to generate readable Markdown
async function generateMarkdown() {
  const fileStream = fs.createReadStream(transcriptFullPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const dialogs = [];
  let userCount = 0;
  let assistantCount = 0;

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const step = JSON.parse(line);
      const type = step.type;
      const source = step.source;
      const time = step.created_at || '';
      const content = step.content || '';

      if (type === 'USER_INPUT' && source === 'USER_EXPLICIT') {
        userCount++;
        dialogs.push({
          role: 'USER',
          time,
          content: content.trim(),
          media: step.media || []
        });
      } else if (type === 'PLANNER_RESPONSE' && content && content.trim().length > 0) {
        // Only take substantial assistant messages
        assistantCount++;
        dialogs.push({
          role: 'ASSISTANT',
          time,
          content: content.trim()
        });
      }
    } catch (e) {
      // ignore json parse error
    }
  }

  console.log(`Extracted ${userCount} user prompts and ${assistantCount} assistant responses.`);

